NAME = 'LvGluck8: Latvian Glück 8th edition'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'Un notikās pēc Mozus, Tā Kunga kalpa, miršanas, tad Tas Kungs runāja uz Jozua, Nuna dēlu, Mozus sulaini, un sacīja:',
        2: 'Mans kalps Mozus ir nomiris; tad nu celies, ej pāri pār šo Jardāni, tu un visi šie ļaudis, uz to zemi, ko Es Israēla bērniem dodu.',
        3: 'Visas vietas, kur jūs savu kāju spersiet, Es jums esmu devis, tā kā Es uz Mozu esmu runājis.',
        4: 'No tuksneša un no šīs Lībanus līdz tai lielai upei, Eifrat upei, visa Hetiešu zeme līdz tai lielai jūrai pret saules noiešanu lai ir jūsu robežas.',
        5: 'Neviens tavā priekšā nepastāvēs visu tavu mūžu; tā kā Es esmu bijis ar Mozu, tāpat Es būšu ar tevi; Es tevi neatstāšu, nedz pametīšu.',
        6: 'Esi stiprs un turi drošu prātu, jo tev šiem ļaudīm būs izdalīt to zemi par iemantojamu tiesu, ko Es viņu tēviem esmu zvērējis dot.',
        7: 'Esi tikai stiprs un turi drošu prātu, ka tu turies un dari pēc visas bauslības, ko Mozus, Mans kalps, tev ir pavēlējis; neatkāpies no tās ne pa labo ne pa kreiso roku, ka tev labi izdodas visur, kur tu iesi.',
        8: 'Lai šī bauslības grāmata neatstājās no tavas mutes, bet apdomā to dienām naktīm, ka tu vari turēt un darīt visu, kas tanī stāv rakstīts: tad tavi ceļi labi izdosies un tad tev laimēsies.',
        9: 'Vai Es tev neesmu pavēlējis: esi stiprs un turi drošu prātu? Nebēdājies un nebaiļojies, jo Tas Kungs, tavs Dievs, ir ar tevi visur, kurp tu iesi.',
        10: 'Tad Jozuas pavēlēja tiem ļaužu virsniekiem un sacīja:',
        11: 'Ejat pa lēģeri un pavēliet tiem ļaudīm sacīdami: sataisiet sev ceļamaizi, jo pēc trim dienām jūs iesiet pār šo Jardāni, ka jūs ieejat, iemantot to zemi, ko Tas Kungs, jūsu Dievs, jums dod par īpašumu.',
        12: 'Un Jozuas runāja uz Rūbeniešiem un Gadiešiem un uz Manasus puscilti un sacīja:',
        13: 'Pieminiet to vārdu, ko Mozus, Tā Kunga kalps, jums ir pavēlējis sacīdams: Tas Kungs, jūsu Dievs, jums dod dusēšanu un jums dod šo zemi.',
        14: 'Jūsu sievas, jūsu bērniņi, jūsu ganāmie pulki lai paliek tai zemē, ko Mozus šaipus Jardānes jums devis, bet jūs ejat apbruņoti savu brāļu priekšā, visi spēcīgie un stiprie vīri, un palīdziet viņiem,',
        15: 'Tiekams Tas Kungs jūsu brāļiem dod dusēšanu tā kā jums, un arī viņi to zemi iemanto, ko Tas Kungs, jūsu Dievs, viņiem dod. Tad jūs griezīsities atpakaļ uz savu pašu zemi un dabūsiet to, ko Mozus, Tā Kunga kalps, jums ir devis šaipus Jardānes pret rītiem.',
        16: 'Tad tie Jozuam atbildēja sacīdami: visu, ko tu mums esi pavēlējis, to mēs darīsim, un visur, kurp tu mūs sūtīsi, mēs iesim.',
        17: 'Tā kā mēs visās lietās esam klausījuši Mozum, tā tev klausīsim, lai tikai Tas Kungs, tavs Dievs, ir ar tevi tā kā Viņš bijis ar Mozu.',
        18: 'Ikvienam, kas tavai mutei turēsies pretī un taviem vārdiem neklausīs iekš visa, ko tu viņam pavēlēsi, tam būs mirt. Esi tikai stiprs un turi drošu prātu.',
    },
    2: {
        1: 'Un Jozuas, Nuna dēls, sūtīja slepeni divus izlūkus no Sitimas sacīdams: ejat, izlūkojiet to zemi un Jēriku. Un tie gāja un nāca kādas sievas namā, tā bija mauka, tai vārds bija Rahaba, un tie tur gulēja.',
        2: 'Un Jērikus ķēniņam tapa sacīts: redzi, šinī naktī vīri nākuši no Israēla bērniem, to zemi izlūkot.',
        3: 'Tad Jērikus ķēniņš sūtīja pie Rahabas un sacīja: dod šurp tos vīrus, kas pie tevis nākuši tavā namā, jo tie ir nākuši, visu šo zemi izlūkot.',
        4: 'Bet tā sieva ņēma tos divus vīrus un tos paslēpa un sacīja tā: tie vīri gan pie manis bija nākuši, bet es nezināju, no kurienes tie bija.',
        5: 'Un kad vārti bija jāaizslēdz, kad metās tumšs, tad tie vīri izgāja. Es nezinu, kurp tie vīri gājuši; dzenaties tiem steigšus pakaļ, tad jūs tos panāksiet.',
        6: 'Bet viņa tiem bija likusi uz jumtu uzkāpt un tos bija paslēpusi apakš linājiem, ko uz jumta bija izklājusi.',
        7: 'Un tie vīri tiem dzinās pakaļ pa Jardānes ceļu līdz tai pārceļamai vietai, un vārti tapa aizslēgti pēc tam, kad bija izgājuši, kas tiem dzinās pakaļ.',
        8: 'Un pirms tie apgūlās, viņa pie tiem uzkāpa uz jumtu.',
        9: 'Un sacīja uz tiem vīriem: es zinu, ka Tas Kungs jums šo zemi devis un ka bailes no jums mums uzkritušas, un ka visi zemes iedzīvotāji jūsu priekšā izbijušies.',
        10: 'Jo mēs esam dzirdējuši, kā Tas Kungs licis izsīkt niedru jūras ūdeņiem jūsu priekšā, jums no Ēģiptes zemes izejot, un ko jūs esat darījuši viņpus Jardānes tiem diviem Amoriešu ķēniņiem, Sihonam un Ogam, ko jūs esat izdeldējuši.',
        11: 'Un to dzirdot mūsu sirds palikusi bailīga, un nav vairs drošības nevienam pret jums; jo Tas Kungs, jūsu Dievs, Viņš ir Dievs augšā debesīs un apakšā virs zemes.',
        12: 'Nu tad zvērējiet man jel pie Tā Kunga, tāpēc ka es žēlastību pie jums esmu darījusi, ka arī jūs darīsiet žēlastību pie mana tēva nama, un dodat man kādu ticamu zīmi,',
        13: 'Ka jūs atstāsiet dzīvus manu tēvu, manu māti un manus brāļus un manas māsas ar visu, kas tiem pieder, un ka jūs mūsu dvēseles izglābsiet no nāves.',
        14: 'Tad tie vīri uz to sacīja: ja mēs nedarīsim žēlastību un uzticību pie tevis, kad Tas Kungs mums šo zemi dos, tad lai mirst mūsu dvēsele jūsu vietā, ja tik jūs šo mūsu lietu nedarīsiet zināmu.',
        15: 'Tad viņa tos ar virvi nolaida pa logu, jo viņas nams bija pie pilsētas mūra un viņa dzīvoja pie tā mūra.',
        16: 'Un viņa uz tiem sacīja: ejat kalnos, ka tie jūs nesastop, kas jums dzenās pakaļ, un paslēpjaties tur trīs dienas, tiekams tie vajātāji atgriezīsies, tad pēc ejat savu ceļu.',
        17: 'Tad tie vīri uz viņu sacīja: mēs būsim vaļā no šī tava zvēresta, ko tu mums lieci zvērēt:',
        18: 'Redzi, kad mēs nākam tai zemē, tad piesien pie sava loga šo sarkano virvi, ar ko tu mūs nolaidi, un sapulcini pie sevis šai namā savu tēvu un savu māti un savus brāļus un visu tava tēva namu.',
        19: 'Un ikviens, kas pa tava nama durvīm izies ārā, tā asinis lai paliek uz viņa galvas, un mēs būsim nevainīgi. Bet ikviens, kas pie tevis būs namā, tā asinis lai paliek uz mūsu galvas, ja kas savu roku pie viņa pieliks.',
        20: 'Bet ja tu šo mūsu lietu darīsi zināmu, tad mēs būsim vaļā no šī zvēresta, ko tu mums likusi zvērēt.',
        21: 'Tad viņa sacīja: lai tā ir, kā jūs sakāt. Un viņa tos atlaida, un tie aizgāja; un viņa to sarkano virvi piesēja pie loga.',
        22: 'Tā tie aizgāja un nāca kalnos un palika tur trīs dienas, tiekams tie vajātāji bija atpakaļ griezušies; jo tie vajātāji tos bija meklējuši pa visiem ceļiem, bet nebija atraduši.',
        23: 'Tad tie divi vīri griezās atpakaļ un nonāca no tiem kalniem un cēlās pāri un nāca pie Jozuas, Nuna dēla, un teica tam visu, kas tiem bija noticis.',
        24: 'Un tie sacīja uz Jozua: tiešām Tas Kungs visu to zemi ir devis mūsu rokās, un visi zemes iedzīvotāji no mums bīstas.',
    },
    3: {
        1: 'Tad Jozuas cēlās no rīta agri, un tie aizgāja no Sitimas un nāca līdz Jardānei, viņš un visi Israēla bērni. Un tie tur palika par nakti, pirms pārcēlās.',
        2: 'Un pēc trim dienām tie virsnieki gāja pa lēģeri',
        3: 'Un pavēlēja tiem ļaudīm sacīdami: kad jūs redzēsiet Tā Kunga, sava Dieva, derības šķirstu un tos priesterus, Levja bērnus, to nesam, tad ceļaties no savas vietas un ejat viņam pakaļ.',
        4: 'Tomēr lai starpa paliek starp jums un viņu līdz divi tūkstošu olekšu plata, un neejat tam tuvu, lai jūs to ceļu varat zināt, kas jums jāiet, jo jūs šo ceļu vēl nekad neesat gājuši.',
        5: 'Un Jozuas sacīja uz tiem ļaudīm: svētījaties, jo rītā Tas Kungs jūsu starpā darīs brīnumus.',
        6: 'Un Jozuas runāja uz tiem priesteriem sacīdams: ņemat derības šķirstu un ejat pāri ļaužu priekšā. Tad tie ņēma derības šķirstu un gāja tiem ļaudīm priekšā.',
        7: 'Un Tas Kungs sacīja uz Jozua: šodien Es sākšu tevi paaugstināt visa Israēla acīs; lai tie zin, ka Es būšu ar tevi, kā esmu bijis ar Mozu.',
        8: 'Un tiem priesteriem, kas to derības šķirstu nes, tev būs pavēlēt un sacīt: kad jūs nākat Jardānes malā pie ūdens, tad apstājaties pie Jardānes.',
        9: 'Un Jozuas sacīja uz Israēla bērniem: nāciet šurp un klausāties Tā Kunga, sava Dieva, vārdus.',
        10: 'Un Jozuas sacīja: pie tam jums būs zināt, ka Tas dzīvais Dievs ir jūsu vidū, un ka Viņš izdzīdams izdzīs jūsu priekšā Kanaāniešus un Hetiešus un Hiviešus un Fereziešus un Ģirgaziešus un Amoriešus un Jebusiešus.',
        11: 'Redzi, visas pasaules valdītāja derības šķirsts ies jūsu priekšā pāri pār Jardāni.',
        12: 'Tad nu ņemat sev divpadsmit vīrus no Israēla ciltīm, no ikvienas cilts vienu vīru.',
        13: 'Un kad to priesteru kājas, kas Tā Kunga, visas pasaules valdītāja, šķirstu nes, nolaidīsies Jardānes ūdenī, tad Jardānes ūdens apstāsies, tas ūdens, kas no augšienes tek, un stāvēs vienā kopā.',
        14: 'Un kad tie ļaudis no saviem dzīvokļiem cēlās, iet pār Jardāni, un tie priesteri nesa derības šķirstu ļaužu priekšā,',
        15: 'Un kad tie šķirsta nesēji nāca līdz Jardānei, un kad to priesteru kājas, kas to šķirstu nesa, upmalā iebrida ūdenī, (bet Jardāne līdz pašām malām ir uzplūdusi cauru pļaujamo laiku),',
        16: 'Tad tas ūdens, kas no augšienes nāca, nostājās stāvu vienā kopā, labi tālu no Adamas pilsētas, kas sānis Cartanai; bet tas, kas tecēja uz leju, klajuma jūrā, (proti) sāls jūrā, tas pavisam izsīka. Tad tie ļaudis gāja pāri, Jērikum pretī.',
        17: 'Bet tie priesteri, kas Tā Kunga derības šķirstu nesa, stāvēja sausumā Jardānes vidū, un viss Israēls gāja pāri pa sausumu, tiekams visi ļaudis bija pārgājuši pār Jardāni.',
    },
    4: {
        1: 'Un kad visi ļaudis bija pārgājuši pār Jardāni, tad Tas Kungs runāja uz Jozua un sacīja:',
        2: 'Ņemat sev divpadsmit vīrus no tiem ļaudīm, no ikvienas cilts vienu vīru,',
        3: 'Un pavēliet tiem sacīdami: paņemiet no šejienes, no Jardānes vidus, kur priesteru kājās stāvējušas, divpadsmit akmeņus un nesiet tos līdz pāri un noliekat tos tai vietā, kur paliksiet par nakti.',
        4: 'Tad Jozuas aicināja tos divpadsmit vīrus, ko viņš no Israēla bērniem bija iecēlis, no ikvienas cilts vienu vīru, un Jozuas uz tiem sacīja:',
        5: 'Noejat Tā Kunga, sava Dieva, šķirsta priekšā Jardānes vidū un paņemat ikkatrs vienu akmeni uz saviem pleciem pēc Israēla bērnu cilšu skaita.',
        6: 'Lai šī ir zīme jūsu starpā, kad jūsu bērni pēclaikā vaicās, sacīdami: kas tie jums par akmeņiem?',
        7: 'Tad jums būs uz tiem sacīt: tādēļ, ka Jardānes ūdens ir izsīcis priekš Tā Kunga derības šķirsta; kad tas gāja caur Jardāni, tad Jardānes ūdens izsīka. Tā lai šie akmeņi Israēla bērniem ir par piemiņu mūžam.',
        8: 'Un Israēla bērni darīja, kā Jozuas tiem bija pavēlējis, un ņēma no Jardānes vidus divpadsmit akmeņus pēc Israēla bērnu cilšu skaita, kā Tas Kungs uz Jozua bija runājis, un tos pārnesa līdz mājas vietā, un tos tur nolika.',
        9: 'Jozuas uzcēla arī divpadsmit akmeņus pašā Jardānes vidū, kur priesteru, derības šķirsta nesēju, kājas bija stāvējušas, un tie tur ir līdz šai dienai.',
        10: 'Un tie priesteri, kas to šķirstu nesa, stāvēja Jardānes vidū, kamēr viss bija izdarīts, ko Tas Kungs Jozuam bija pavēlējis, uz tiem ļaudīm runāt, pēc visa, ko Mozus Jozuam bija pavēlējis; un tie ļaudis steidzās un gāja pāri.',
        11: 'Un kad tie ļaudis bija pārgājuši, tad Tā Kunga šķirsts gāja pāri un tie priesteri ļaužu priekšā.',
        12: 'Rūbena bērni un Gada bērni un Manasus puscilts apbruņoti gāja Israēla bērnu priekšā, kā Mozus uz tiem bija runājis.',
        13: 'Pie četrdesmit tūkstošu apbruņotu karavīru gāja karā Tā Kunga priekšā Jērikus klajumos.',
        14: 'Tai dienā Tas Kungs Jozua paaugstināja visa Israēla acīs, un tie viņu bijās, tā kā tie bija Mozu bijušies visas viņa mūža dienas.',
        15: 'Un Tas Kungs runāja uz Jozua un sacīja:',
        16: 'Pavēli tiem priesteriem, kas derības šķirstu nes, lai tie izkāpj no Jardānes.',
        17: 'Tad Jozuas tiem priesteriem pavēlēja un sacīja: izkāpiet no Jardānes.',
        18: 'Un kad tie priesteri, kas Tā Kunga derības šķirstu nesa, izkāpa no Jardānes vidus, un kad priesteru kājas nāca sausumā, tad Jardānes ūdens griezās atpakaļ savā vietā un pārplūda kā papriekš visur savos krastos.',
        19: 'Bet pirmā mēneša desmitā dienā tie ļaudis no Jardānes izkāpa un apmetās Gilgalā, Jērikum pret rītiem.',
        20: 'Un Jozuas uzcēla Gilgalā tos divpadsmit akmeņus, ko tie no Jardānes bija paņēmuši.',
        21: 'Un viņš runāja uz Israēla bērniem sacīdams: kad jūsu bērni turpmāk saviem tēviem vaicās un sacīs: kas tie par akmeņiem?',
        22: 'Tad jums būs stāstīt saviem bērniem un sacīt: Israēls ir gājis pa sausumu caur šo Jardāni.',
        23: 'Jo Tas Kungs, jūsu Dievs, Jardānes ūdenim jūsu priekšā ir licis izsīkt, tiekams jūs bijāt pārgājuši, kā Tas Kungs, jūsu Dievs, bija darījis niedru jūrā; tai Viņš arī lika izsīkt mūsu priekšā, tiekams bijām gājuši cauri.',
        24: 'Lai visas zemes tautas atzīst Tā Kunga roku, ka tā ir stipra, lai jūs bīstaties To Kungu, savu Dievu, visu mūžu.',
    },
    5: {
        1: 'Un notikās, kad visi Amoriešu ķēniņi, kas viņpus Jardānes pret jūru un visi Kanaāniešu ķēniņi, kas jūrmalā, dzirdēja, ka Tas Kungs bija licis izsīkt Jardānes ūdenim Israēla bērnu priekšā, tiekams tie bija gājuši cauri, tad viņu sirds tapa bailīga, un tiem izzuda drošība Israēlu bērnu priekšā.',
        2: 'Tanī laikā Tas Kungs sacīja uz Jozua: taisi sev akmens nažus un apgraizī atkal Israēla bērnus otru reiz.',
        3: 'Tad Jozuas taisīja sev akmens nažus un apgraizīja Israēla bērnus uz Aralot pakalna.',
        4: 'Un tādēļ Jozuas tos apgraizīja: visi ļaudis no vīriešu kārtas, kas no Ēģiptes zemes bija izgājuši, visi kara vīri bija nomiruši tuksnesī uz ceļa, no Ēģiptes zemes nākot.',
        5: 'Jo visi ļaudis, kas izgāja, bija apgraizīti. Bet visi ļaudis, kas bija dzimuši tuksnesī, ceļā no Ēģiptes zemes nākot, tie nebija apgraizīti.',
        6: 'Jo Israēla bērni staigāja četrdesmit gadus tuksnesī, tiekams bija izmiruši visi karavīri, kas no Ēģiptes zemes bija izgājuši, tādēļ ka Tā Kunga balsij nebija klausījuši; tiem Tas Kungs bija zvērējis, ka Viņš tiem to zemi negribot ļaut redzēt, ko Viņš viņu tēviem bija zvērējis, mums dot, zemi, kur piens un medus tek.',
        7: 'Bet viņu dēlus Viņš cēla viņu vietā; tos Jozuas apgraizīja, tāpēc ka tiem bija priekšāda, jo tie nebija apgraizīti ceļā.',
        8: 'Un kad visi ļaudis bija apgraizīti, tad tie palika savā vietā lēģerī, tiekams bija dziedināti.',
        9: 'Un Tas Kungs sacīja uz Jozua: šodien Es no jums esmu novērsis visu Ēģiptes kaunu. Tāpēc tās vietas vārds tapa nosaukts Gilgala (novēršana) līdz šai dienai.',
        10: 'Un Israēla bērni apmetās Gilgalā, un turēja Pasa svētkus mēneša četrpadsmitā dienā ap vakaru, Jērikus klajumos,',
        11: 'Un ēda Pasa svētku otrā dienā no tās zemes labības neraudzētu maizi un ceptas vārpas šinī dienā.',
        12: 'Un tas manna beidzās otrā dienā pēc tam, kad tie bija ēduši no tās zemes labības, un tur nebija vairs manna Israēla bērniem, bet tie ēda to gadu no Kanaāna zemes augļiem.',
        13: 'Un kad Jozuas bija pie Jērikus, tad viņš pacēla savas acis, un redzēja, un raugi, tur viens vīrs viņam stāvēja pretī, tam bija izvilkts zobens rokā, un Jozuas pie viņa gāja un sacīja: vai tu esi no mūsējiem vai no mūsu pretiniekiem?',
        14: 'Un tas sacīja: nē, bet es esmu Tā Kunga karaspēka virsnieks, tagad es esmu nācis. Tad Jozuas metās zemē uz savu vaigu un to pielūdza un uz to sacīja: ko mans Kungs runā uz savu kalpu?',
        15: 'Tad Tā Kunga karaspēka virsnieks sacīja uz Jozua: novelc savas kurpes no savām kājām, jo tā vieta, kur tu stāvi, ir svēta. Un Jozuas tā darīja.',
    },
    6: {
        1: 'Un Jērikus aizslēdza vārtus un bija aizslēgts priekš Israēla bērniem; tur neviens ne izgāja, ne iegāja.',
        2: 'Tad Tas Kungs sacīja uz Jozua: redzi, Jēriku ar viņa ķēniņu un stipriem karavīriem Es dodu tavā rokā.',
        3: 'Un ejat ap pilsētu, visi kara vīri visapkārt ap pilsētu vienreiz; tā dari sešas dienas.',
        4: 'Un septiņi priesteri lai nes septiņas gaviles bazūnes tā šķirsta priekšā, un septītā dienā ejat septiņas reizes ap pilsētu un tie priesteri lai pūš bazūnes.',
        5: 'Un kad tie pūtīs gaviles bazūni un jūs dzirdēsiet bazūnes skaņu, tad lai visi ļaudis kliedz lielā kliegšanā, un pilsētas mūri sagrūs, un tie ļaudis lai kāpj iekšā, kur katrs stāvēdams.',
        6: 'Tad Jozuas, Nuna dēls, aicināja tos priesterus un uz tiem sacīja: nesiet derības šķirstu, un lai septiņi priesteri nes septiņas gaviles bazūnes Tā Kunga šķirsta priekšā.',
        7: 'Un uz tiem ļaudīm viņš sacīja: ejat apkārt ap pilsētu, un tie apbruņotie lai iet Tā Kunga šķirsta priekšā.',
        8: 'Un kā Jozuas uz tiem ļaudīm bija sacījis, tā tie septiņi priesteri gāja nesdami septiņas gaviles bazūnes Tā Kunga priekšā, tie gāja un pūta bazūnes, un Tā Kunga derības šķirsts tiem gāja pakaļ.',
        9: 'Un tie apbruņotie gāja to priesteru priekšā, kas bazūnes pūta, un tas pulks gāja tam šķirstam pakaļ, ejot bazūnes pūzdami.',
        10: 'Un Jozuas tiem ļaudīm bija pavēlējis sacīdams: jums nebūs kliegt, un lai jūsu balss netop dzirdēta, un lai ne vārds neiziet no jūsu mutes līdz tai dienai, kad es jums sacīšu: kliedzat! Tad jums būs kliegt.',
        11: 'Un Tā Kunga šķirsts gāja ap pilsētu apkārt vienreiz; tad tie nāca atkal lēģerī un palika par nakti lēģerī.',
        12: 'Un Jozuas cēlās no rīta agri, un tie priesteri nesa Tā Kunga šķirstu.',
        13: 'Un tie septiņi priesteri, kas tās septiņas gaviles bazūnes nesa Tā Kunga šķirsta priekšā, gāja un ejot pūta bazūnes un tie apbruņotie gāja viņiem pa priekšu, un tas pulks gāja Tā Kunga šķirstam pakaļ, un ejot pūta bazūnes.',
        14: 'Un otrā dienā tie gāja ap pilsētu vienreiz un griezās atkal lēģerī; tā tie darīja sešas dienas.',
        15: 'Un septītā dienā tie cēlās agri, gaismai austot, un gāja ap pilsētu tādā pašā kārtā septiņas reizes; tik vien šai dienā tie gāja ap pilsētu septiņas reizes.',
        16: 'Un septītā reizē, kad tie priesteri bazūnes pūta, Jozuas sacīja uz tiem ļaudīm: kliedzat, jo Tas Kungs jums to pilsētu ir devis.',
        17: 'Un tā pilsēta un viss, kas tur ir, Tam Kungam lai top izdeldēts; Rahaba tikai, tā mauka, lai paliek dzīva, un visi, kas pie viņas ir namā, jo viņa ir paslēpusi tos vīrus, ko bijām izsūtījuši.',
        18: 'Tikai sargājaties no tā izdeldējamā, ka jūs paši netopat izdeldēti, un neņemat no tā izdeldējamā, un nedarāt, ka Israēla lēģeris netop izdeldēts, un nevedat to postā.',
        19: 'Bet viss sudrabs un zelts un vara un dzelzs rīki, - tas lai Tam Kungam ir svēts, tam būs nākt pie Tā Kunga mantas.',
        20: 'Tad nu tie ļaudis kliedza, un bazūnes tapa pūstas. Un notikās, kad tie ļaudis dzirdēja bazūnes skaņu, tad tie ļaudis kliedza lielā kliegšanā, un tas mūris sagruva, un tie ļaudis kāpa pilsētā, kur katrs stāvēdams,',
        21: 'Un tie uzņēma to pilsētu un izdeldēja ar zobena asmeni visu, kas pilsētā bija, vīrus un sievas, bērnus un vecos līdz ar vēršiem un sīkiem lopiem un ēzeļiem.',
        22: 'Tad Jozuas sacīja tiem diviem vīriem, tās zemes izlūkiem: ejat tās sievas, tās maukas, namā, un izvediet no turienes to sievu un visu, kas tai pieder, kā jūs tai esat zvērējuši.',
        23: 'Tad tie jaunekļi, tie izlūki, gāja un izveda Rahabu un viņas tēvu un viņas māti un viņas brāļus un visu, kas tai piederēja; tie izveda arī visus viņas radus un lika tiem palikt ārā priekš Israēla lēģera.',
        24: 'Un to pilsētu tie sadedzināja ar uguni, un visu, kas tur bija; bet to sudrabu un zeltu līdz ar tiem vara un dzelzs rīkiem, to tie lika pie Tā Kunga nama mantas.',
        25: 'Bet to mauku Rahabu un viņas tēva namu, un visu, kas tai piederēja, Jozuas pameta dzīvu, un tā dzīvo Israēla vidū līdz šai dienai, tāpēc ka viņa bija paslēpusi tos vīrus, ko Jozuas bija izsūtījis, Jēriku izlūkot.',
        26: 'Un tanī laikā Jozuas zvērēja un sacīja: nolādēts lai ir tas vīrs Tā Kunga priekšā, kas celsies un uztaisīs šo pilsētu Jēriku! Pamatu tas lai liek par savu pirmdzimto un vārtus lai ceļ par savu jaunāko!',
        27: 'Tā Tas Kungs bija ar Jozua, un viņa slava izpaudās pa visu zemi.',
    },
    7: {
        1: 'Bet Israēla bērni noziedzās pie tā izdeldējamā, jo Akans, Karmus dēls, tas bija Zabdus, tas Zerus dēls no Jūda cilts, ņēma no tā izdeldējamā. Tad Tā Kunga bardzība iedegās pret Israēla bērniem.',
        2: 'Kad nu Jozuas izsūtīja vīrus no Jērikus uz Aju pie Bet-Avenas, no Bēteles pret rītiem, un uz tiem runāja sacīdams: noejat un izlūkojiet to zemi,',
        3: 'Tad tie vīri nogāja un izlūkoja Aju, un griezās atpakaļ pie Jozuas un uz to sacīja: lai visi ļaudis nenoiet, bet lai kādi divtūkstoš vai trīstūkstoš vīri noiet un Aju kauj, neapgrūtini visus ļaudis, jo viņu tur ir maz.',
        4: 'Tad no tiem ļaudīm cēlās uz turieni trīstūkstoš vīri, bet tiem bija jābēg priekš Ajas vīriem.',
        5: 'Un Ajas vīri apkāva no tiem trīsdesmit un sešus vīrus un dzinās tiem pakaļ no vārtiem līdz Zabarim, un tos sakāva pakalnē. Tad to ļaužu sirds izkusa un palika kā ūdens.',
        6: 'Un Jozuas saplēsa savas drēbes un metās zemē uz savu vaigu priekš Tā Kunga šķirsta līdz pat vakaram, viņš un Israēla vecaji, un tie kaisīja pīšļus uz savām galvām.',
        7: 'Un Jozuas sacīja: ak Kungs, Dievs! Kāpēc tu šiem ļaudīm esi licis iet caur Jardāni, mūs dodams Amoriešu rokās, ka tie mūs izdeldē? Ak, kaut mēs mierā būtu palikuši viņpus Jardānes.',
        8: 'Ak Kungs, ko lai saku, kad nu Israēls muguru griež saviem ienaidniekiem?',
        9: 'Kad Kanaānieši un visi zemes iedzīvotāji to dzirdēs, tad tie mūs apstās visapkārt un izdeldēs mūsu vārdu no zemes. Ko tad Tu darīsi Sava lielā Vārda dēļ?',
        10: 'Tad Tas Kungs sacīja uz Jozua: celies, kāpēc tu tā guli uz sava vaiga?',
        11: 'Israēls ir apgrēkojies un arī pārkāpis Manu derību, ko Es tiem esmu pavēlējis; tie ir arī ņēmuši no tā izdeldējamā un ir zaguši un slēpuši un to ir likuši pie savas mantas.',
        12: 'Tāpēc Israēla bērni nevar pastāvēt priekš saviem ienaidniekiem, tiem bēdzin jābēg no saviem ienaidniekiem, jo tie ir izdeldējami. Es nebūšu vairs ar jums, ja jūs to, kas izdeldējams, no sava vidus neizdeldēsiet.',
        13: 'Celies, svētī tos ļaudis un saki: svētījaties uz rītdienu, jo tā saka Tas Kungs, Israēla Dievs: izdeldējama lieta ir tavā vidū, Israēl; tu nevari pastāvēt priekš saviem ienaidniekiem, tiekams tu nebūsi izdeldējis no sava vidus to izdeldējamo.',
        14: 'Rītā agri nākat priekšā pēc savām ciltīm, un tā cilts, ko Tas Kungs uzrādīs, lai nāk priekšā pēc saviem radiem, un tas rads, ko Tas Kungs uzrādīs, lai nāk priekšā pēc savām saimēm, un tā saime, ko Tas Kungs uzrādīs, lai nāk priekšā pēc saviem vīriem.',
        15: 'Un kas taps atrasts ar to izdeldējamo, to būs sadedzināt ar uguni, līdz ar visu, kas tam pieder, tāpēc ka viņš pārkāpis Tā Kunga derību, un tāpēc ka viņš kauna lietu darījis iekš Israēla.',
        16: 'Tad Jozuas cēlās no rīta agri un veda priekšā Israēli pēc viņu ciltīm, - tad Jūda cilts tapa uzrādīta.',
        17: 'Un kad viņš Jūda cilti veda priekšā, tad tapa uzrādīts Zeraiešu rads, un kad Zeraiešu radu veda priekšā pēc tiem saimniekiem, tad Zabdus tapa uzrādīts.',
        18: 'Kad šo saimi veda priekšā pēc tiem vīriem, tad Akans tapa uzrādīts, Karmus dēls, tas bija Zabdus, tas Zerus dēls no Jūda cilts.',
        19: 'Tad Jozuas sacīja uz Akanu: mans dēls, dod jel Tam Kungam, Israēla Dievam, godu un dod Viņam slavu un stāsti man jel, ko tu esi darījis, un neslēpi to man.',
        20: 'Tad Akans atbildēja Jozuam un sacīja: tiešām, es esmu apgrēkojies pret To Kungu, Israēla Dievu, un esmu tā un tā darījis.',
        21: 'Jo es ieraudzīju pie laupījuma vienu skaistu Babiloniešu mēteli un divsimt sudraba sēķeļus un vienu zelta sprādzi, tā svēra piecdesmit sēķeļus, un es tās lietas iekāroju un tās ņēmu, un redzi, tās manā teltī ir paslēptas zemē un tas sudrabs tur apakšā.',
        22: 'Tad Jozuas sūtīja vīrus un tie skrēja uz to telti, un redzi, tas bija apslēpts viņa teltī, un tas sudrabs tur apakšā.',
        23: 'Un tie to izņēma no tās telts un atnesa pie Jozuas un pie visiem Israēla bērniem un to izbēra Tā Kunga priekšā.',
        24: 'Tad Jozuas un viss Israēls līdz ar viņu ņēma Akanu, Zerus dēlu, un to sudrabu un to mēteli un to zelta sprādzi un viņa dēlus un viņa meitas un viņa vēršus un viņa ēzeļus un viņa sīkos lopus un viņa telti un visu, kas tam bija, un tos veda uz Ahora ieleju.',
        25: 'Un Jozuas sacīja: kā tu mūs esi apbēdinājis, tā tev Tas Kungs šodien apbēdinās; un viss Israēls to akmeņiem nomētāja un tos sadedzināja ar uguni un uzkrāva pār tiem akmeņus.',
        26: 'Un tie uzcēla pār tiem lielu akmeņu kopu, kas stāv līdz šai dienai. Tā Tas Kungs atgriezās no Savas bardzības karstuma; tādēļ tās vietas vārds top nosaukts Ahora ieleja līdz šai pašai dienai.',
    },
    8: {
        1: 'Tad Tas Kungs sacīja uz Jozua: nebīsties un nebaiļojies! Ņem līdz visus karavīrus un celies pret Aju; redzi, Es esmu devis tavā rokā Ajas ķēniņu un viņa ļaudis, viņa pilsētu un viņa zemi.',
        2: 'Un dari Ajai un viņas ķēniņam, kā tu esi darījis Jērikum un viņa ķēniņam, tikai lai jūs viņas laupījumu un viņas lopus priekš sev ņemat. Liec citiem paslēpties aiz pilsētas.',
        3: 'Tad Jozuas un visi karavīri cēlās, iet uz Aju, un Jozuas izlasīja trīsdesmit tūkstošus spēcīgu un stipru vīru, un tos izsūtīja naktī,',
        4: 'Un tiem pavēlēja sacīdams: raugāt, jums pret to pilsētu būs paslēpties aiz pilsētas; neturaties visai tālu no pilsētas un esiet visi gatavi.',
        5: 'Es tad un visi tie ļaudis, kas pie manis, pieiesim pie pilsētas, un kad tie izies mums pretī tā kā pirmo reiz, tad mēs no viņiem bēgsim.',
        6: 'Lai tie tad nāk ārā mums pakaļ, kamēr mēs tos no pilsētas atšķiram, jo tie sacīs: viņi bēg mūsu priekšā, tā kā pirmo reiz, - un mēs bēgsim no viņiem.',
        7: 'Bet jūs ceļaties no tās vietas, kur bijāt slēpušies, un uzņemat to pilsētu, jo Tas Kungs, jūsu Dievs, to devis jūsu rokā.',
        8: 'Un kad jūs to pilsētu esat uzņēmuši tad jums to pilsētu būs sadedzināt ar uguni, pēc Tā Kunga vārda jums būs darīt; redziet, es jums to esmu pavēlējis.',
        9: 'Tā Jozuas tos izsūtīja. Un tie gāja paslēpties un turējās starp Bēteli un Aju, Ajai pret vakariem, bet Jozuas palika to nakti pie tiem ļaudīm.',
        10: 'Un Jozuas cēlās no rīta agri un pārlūkoja tos ļaudis, un viņš un Israēla vecaji cēlās tiem ļaudīm priekšā pret Aju.',
        11: 'Tā līdz arīdzan visi karavīri, kas pie tā bija, cēlās un piegāja un nāca pret to pilsētu un apmetās pret ziemeļa pusi no Ajas, un tur bija ieleja starp tiem un Aju.',
        12: 'Un viņš ņēma kādus piectūkstoš vīrus un tiem lika paslēpties starp Bēteli un Aju, pilsētai pret vakariem.',
        13: 'Un tie nostādīja tos ļaudis, visu to lēģeri, kas bija pret pilsētas ziemeļa pusi, un viņa pakaļējo pulku pret pilsētas vakara pusi, un Jozuas tanī naktī nogāja pašā ielejā.',
        14: 'Un kad Ajas ķēniņš to redzēja, tad tie pilsētas vīri steidzās un cēlās no rīta agri un izgāja Israēlim pretī uz kaušanos, viņš un visi viņa ļaudis, norunātā vietā klajuma priekšā, bet viņš nezināja, ka citi bija paslēpušies aiz pilsētas.',
        15: 'Un Jozuas un viss Israēls izlikās kauti esoši viņu priekšā un bēga pa tuksneša ceļu.',
        16: 'Tāpēc visi ļaudis, kas bija pilsētā, tapa sasaukti, ka tiem dzītos pakaļ.',
        17: 'Un tie dzinās Jozuam pakaļ un šķīrās nost no pilsētas, un tur neatlika neviena vīra Ajā un Bētelē, kas nebūtu izgājis Israēlim pakaļ, un tie pameta pilsētu atvērtu un dzinās Israēlim pakaļ.',
        18: 'Tad Tas Kungs sacīja uz Jozua: izstiep to šķēpu, kas tavā rokā, pret Aju, jo Es to došu tavā rokā. Tad Jozuas izstiepa to šķēpu, kas bija viņa rokā, pret to pilsētu.',
        19: 'Tad tie, kas bija paslēpušies, tūdaļ cēlās no savas vietas un skrēja, kad viņš savu roku izstiepa, un nāca pilsētā un to uzņēma un steidzās un iededzināja to pilsētu ar uguni.',
        20: 'Kad nu Ajas ļaudis atpakaļ griezās, tad tie skatījās, un redzi, pilsētas dūmi cēlās pret debesi, un tie nespēja nekur bēgt, ne šurp, ne turp, jo tie ļaudis, kas uz tuksnesi bēga, griezās atpakaļ pret tiem, kas dzinās pakaļ.',
        21: 'Jo kad Jozuas un viss Israēls redzēja, ka tie, kas bija paslēpušies, pilsētu bija uzņēmuši un ka pilsētas dūmi cēlās, tad viņi arīdzan griezās atpakaļ un kāva Ajas vīrus.',
        22: 'Un tad arī tie no pilsētas nāca ārā viņiem pretī, tā ka tie bija vidū starp Israēli, šie no tejienes un viņi no turienes, un tie tos kāva, kamēr neviens no tiem neatlika nedz izbēga.',
        23: 'Bet Ajas ķēniņu tie sagūstīja dzīvu un veda pie Jozuas.',
        24: 'Un kad Israēls bija nokāvis visus Ajas iedzīvotājus, laukā un tuksnesī, uz kurieni tie viņiem bija dzinušies pakaļ, un kad tie visi caur zobena asmeni bija krituši līdz pēdīgam, tad viss Israēls griezās atpakaļ uz Aju, un to sita ar zobena asmeni.',
        25: 'Un visi, kas tai dienā krita, vīri un sievas, bija divpadsmit tūkstoši; tie bija visi Ajas ļaudis.',
        26: 'Un Jozuas neatvilka savu roku, ko viņš ar šķēpu bija izstiepis, tiekams viņš nebija izdeldējis visus Ajas iedzīvotājus.',
        27: 'Tikai lopus un pilsētas laupījumu Israēls laupīja priekš sevis pēc Tā Kunga vārda, ko viņš Jozuam bija pavēlējis.',
        28: 'Un Jozuas sadedzināja Aju un to padarīja par mūžīgu postažas vietu līdz šai dienai.',
        29: 'Un Ajas ķēniņu viņš pakāra pie koka līdz vakaram, un kad saule nogāja, Jozuas pavēlēja, viņa miesas noņemt no koka, un tie viņu nometa pie pilsētas vārtiem un uzkrāva pār viņu lielu akmeņu kopu līdz šai dienai.',
        30: 'Tad Jozuas uztaisīja altāri Tam Kungam, Israēla Dievam, Ebala kalnā,',
        31: 'Tā kā Mozus, Tā Kunga kalps, Israēla bērniem bija pavēlējis, kā Mozus bauslības grāmatā stāv rakstīts, altāri no veseliem akmeņiem, kur dzelzs ierocis nebija pielikts, un uz tā tie upurēja Tam Kungam dedzināmos upurus un upurēja arī pateicības upurus.',
        32: 'Un viņš rakstīja uz tiem akmeņiem norakstu no Mozus bauslības, ko šis bija rakstījis priekš Israēla bērniem.',
        33: 'Un viss Israēls ar saviem vecajiem un virsniekiem un soģiem stāvēja abējos šķirsta sānos pretim tiem priesteriem un Levitiem, kas Tā Kunga derības šķirstu nesa, gan svešinieki, gan pašu ļaudis, viena puse pret Gerizim kalnu un otra puse pret Ebalkalnu, tā kā Mozus, Tā Kunga kalps, iepriekš bija pavēlējis, tos ļaudis svētīt.',
        34: 'Un pēc tam viņš izlasīja visus bauslības vārdus, svētību un lāstu, kā bauslības grāmatā stāv rakstīts.',
        35: 'Tur nebija neviena vārda no visiem, cik Mozus bija pavēlējis, ko Jozuas nebūtu izlasījis priekš visas Israēla draudzes un tām sievām un tiem bērniņiem un tiem svešiniekiem, kas staigāja viņu vidū.',
    },
    9: {
        1: 'Un kad to dzirdēja visi ķēniņi, kas viņpus Jardānes bija, kalnos un ielejās un gar visu lielās jūras malu, Lībanum pretī, Hetieši un Amorieši, Ferezieši, Hivieši un Jebusieši,',
        2: 'Tad tie sapulcējās visi kopā, kauties ar Jozua un ar Israēli.',
        3: 'Kad nu Gibeonas iedzīvotāji dzirdēja, ko Jozuas bija darījis ar Jēriku un ar Aju, tad tie arīdzan darīja viltu',
        4: 'Un nogāja un likās vēstneši ejoši un ņēma vecus maisus uz saviem ēzeļiem,',
        5: 'Un vecus saplīsušus un lāpītus ādas vīna traukus, arī vecas un lāpītas kurpes savās kājās, un tiem bija arī vecas drēbes mugurā, un visa viņu ceļamaize bija sakaltusi un sapelējusi.',
        6: 'Un tie gāja pie Jozuas Gilgalas lēģerī un sacīja uz to un uz Israēla vīriem: mēs no tālas zemes esam nākuši; tad dariet nu ar mums derību.',
        7: 'Tad Israēla vīri sacīja uz to Hivieti: varbūt, ka tu dzīvo mūsu vidū, kā tad mēs ar tevi varam darīt derību?',
        8: 'Tad tie sacīja uz Jozua: mēs esam tavi kalpi. Tad Jozuas uz tiem sacīja: kas jūs esat un no kurienes jūs nākat?',
        9: 'Tie uz viņu sacīja: tavi kalpi nākuši no varen tālas zemes, Tā Kunga, tava Dieva, vārda dēļ; jo mēs esam dzirdējuši Viņa slavu un visu, ko Viņš darījis Ēģiptes zemē.',
        10: 'Un visu, ko Viņš darījis tiem diviem Amoriešu ķēniņiem, kas viņpus Jardānes bija, Sihonam, Hešbonas ķēniņam, un Ogam, Basanas ķēniņam, kas Astarotā dzīvoja.',
        11: 'Tāpēc mūsu vecaji un visi, kas mūsu zemē dzīvo, uz mums runāja un sacīja: ņemiet savās rokās ceļamaizi un ejat viņiem pretī un sakāt uz tiem: mēs esam jūsu kalpi; un nu dariet ar mums derību.',
        12: 'Šo savu maizi mēs jaunu no savām mājām uz ceļu esam paņēmuši līdz, tai dienā, kad mēs izgājām pie jums nākt, bet redzi, nu tā sakaltusi un sapelējusi.',
        13: 'Un šie ādas vīna trauki, ko mēs pildījām, bija jauni, bet redzi, tie ir saplīsuši un šīs mūsu drēbes un mūsu kurpes ir vecas palikušas no tā varen tālā ceļa.',
        14: 'Tad tie vīri ņēma no viņu ceļamaizes un nevaicāja Tā Kunga muti.',
        15: 'Un Jozuas derēja mieru ar tiem un darīja derību ar tiem, tos atstāt dzīvus, un tie draudzes virsnieki tiem zvērēja.',
        16: 'Un pēc trim dienām, kad tie derību ar tiem bija darījuši, tad tie dzirdēja, viņus no tuvienes esam un dzīvojam viņu vidū.',
        17: 'Jo kad Israēla bērni cēlās, tad tie nāca trešā dienā pie viņu pilsētām. Bet viņu pilsētas bija Gibeona, Kavira un Beērote un Kiriat-Jearima.',
        18: 'Un Israēla bērni tos nekāva, tāpēc ka draudzes virsnieki tiem bija zvērējuši pie Tā Kunga, Israēla Dieva; tāpēc visa draudze kurnēja pret tiem virsniekiem.',
        19: 'Tad visi tie virsnieki uz visu draudzi sacīja: mēs pie Tā Kunga, Israēla Dieva, tiem esam zvērējuši, tāpēc mēs tos nu nevaram aizskart.',
        20: 'Bet mēs tiem darīsim tā: pametīsim tos dzīvus, ka nekāda dusmība pār mums nenāk tā zvēresta dēļ, ko mēs tiem esam zvērējuši.',
        21: 'Tad tie virsnieki uz tiem sacīja: lai paliek dzīvi; un tie bija malkas cirtēji un ūdens smēlēji visai draudzei, kā tie virsnieki tiem bija runājuši.',
        22: 'Un Jozuas tos aicināja un uz tiem runāja sacīdams: kāpēc jūs mūs esat pievīluši sacīdami, mēs esam ļoti tālu no jums, - un jūs tomēr mūsu vidū dzīvojat?',
        23: 'Nu tad esat nolādēti, ka no jums netrūkst kalpu un malkas cirtēju un ūdens smēlēju priekš mūsu Dieva nama.',
        24: 'Tie atbildēja Jozuam un sacīja: taviem kalpiem tapa stāstīts, ko Tas Kungs, tavs Dievs, Mozum Savam kalpam, ir pavēlējis, ka Viņš jums visu to zemi grib dot, un visus tos, kas tai zemē dzīvo, no jūsu priekšas izdeldēt, tad mēs savas dzīvības dēļ ļoti bijāmies no jums un tā darījām.',
        25: 'Un nu redzi, mēs esam tavā rokā, dari mums, tā kā darīt tavās acīs rādās labi un taisni.',
        26: 'Tad viņš tiem tā darīja un tos izglāba no Israēla bērnu rokas, ka tie tos nenokāva.',
        27: 'Un Jozuas tai dienā tos nodeva draudzei par malkas cirtējiem un ūdens smēlējiem un priekš Tā Kunga altāra līdz šai dienai tai vietā, ko Viņš izredzētu.',
    },
    10: {
        1: 'Un kad Adonicedeķs, Jeruzālemes ķēniņš, dzirdēja, ka Jozuas Aju bija uzņēmis un izdeldējis, un Ajai un viņas ķēniņam tā darījis, kā viņš Jērikum un viņa ķēniņam bija darījis, un ka tie, kas Gibeonā dzīvoja, ar Israēli bija derējuši mieru un starp tiem dzīvoja.',
        2: 'Tad tie ļoti bijās, jo Gibeona bija liela pilsēta, tā kā viena ķēniņa pilsēta, lielāka nekā Aja, un visi viņas vīri bija stipri.',
        3: 'Tāpēc Adonicedeķs, Jeruzālemes ķēniņš, sūtīja pie Oāma, Hebronas ķēniņa, un pie Pireama, Jarmutes ķēniņa, un pie Javiūs, Lāķisas ķēniņa, un pie Debira, Eglonas ķēniņa, sacīdams:',
        4: 'Nāciet pie manis un palīdziet man, lai Gibeonu kaujam, jo tā mieru derējusi ar Jozua un ar Israēla bērniem.',
        5: 'Tad sapulcējās un cēlās pieci Amoriešu ķēniņi: Jeruzālemes ķēniņš, Hebronas ķēniņš, Jarmutes ķēniņš, Lāķisas ķēniņš, Eglonas ķēniņš, līdz ar visiem saviem karapulkiem un apmetās pret Gibeonu un karoja pret viņu.',
        6: 'Un Gibeonas vīri sūtīja pie Jozuas lēģerī uz Gilgalu sacīdami: neatrauj savu roku no saviem kalpiem; nāc steigšus un izglāb mūs un palīdzi mums, jo visi Amoriešu ķēniņi, kas kalnos dzīvo, pret mums sapulcējušies.',
        7: 'Tad Jozuas cēlās no Gilgalas, pats un visi kara ļaudis līdz ar viņu, un visi spēka vīri.',
        8: 'Un Tas Kungs sacīja uz Jozua: nebīsties no viņiem, jo Es tos esmu nodevis tavā rokā, neviens nepastāvēs tavā priekšā.',
        9: 'Un Jozuas piepeši viņiem uzbruka, cauru nakti no Gilgalas uz augšu iedams.',
        10: 'Un Tas Kungs tos izbiedēja Israēla priekšā, un viņš tos kāva ar lielu kaušanu Gibeonā un tiem dzinās pakaļ pa to ceļu augšup uz Bet-Oronu un tos kāva līdz Āzekai un Maķedai.',
        11: 'Un kad tie no Israēla bēga lejā no Bet-Orona, tad Tas Kungs lielus krusas gabalus no debess uz tiem nometa līdz Āzekai, ka tie nomira; tur bija vairāk, kas no krusas nomira, nekā ko Israēla bērni ar zobenu nokāva.',
        12: 'Tad Jozuas runāja uz To Kungu tai dienā, kad Tas Kungs Amoriešus nodeva Israēla priekšā, un sacīja Israēla priekšā: Saule, apstājies Gibeonā, un mēnesi, Ajalones ielejā.',
        13: 'Tad saule apstājās un mēnesis stāvēja, tiekams tie ļaudis pie saviem ienaidniekiem bija atriebušies. Vai tas nav rakstīts tā taisnā grāmatā: Tā saule stāvēja debess vidū un nesteidzās noiet veselu dienu.',
        14: 'Un tādas dienas kā šī nebija, ne priekš viņas, ne pēc viņas, ka Tas Kungs cilvēka balsi paklausīja; jo Tas Kungs karoja par Israēli.',
        15: 'Tad Jozuas griezās atpakaļ un viss Israēls līdz ar viņu uz Gilgalas lēģeri.',
        16: 'Bet tie pieci ķēniņi bija bēguši un apslēpušies tai alā pie Maķedas.',
        17: 'Un Jozuam tapa teikts un sacīts: tie pieci ķēniņi ir atrasti, apslēpušies tai alā pie Maķedas.',
        18: 'Tad Jozuas sacīja: pieveļat lielus akmeņus priekš alas cauruma un liekat vīrus priekšā, viņus sargāt.',
        19: 'Bet jūs nestāviet mierā, dzenaties saviem ienaidniekiem pakaļ un kaujiet viņu pakaļējos, neļaujat tiem savās pilsētās nākt, jo Tas Kungs, jūsu Dievs, tos ir nodevis jūsu rokā.',
        20: 'Un kad Jozuas un Israēla bērni bija beiguši tos kaut ar ļoti lielu kaušanu, kamēr tie bija izdeldēti, un kad tie atlikušie no tiem bija glābušies un nākuši stiprās pilsētās,',
        21: 'Tad visi ļaudis ar mieru griezās atpakaļ pie Jozuas uz lēģeri pie Maķedas; neviens pret Israēla bērniem pat ne mēli nekustināja.',
        22: 'Un Jozuas sacīja: atdariet tās alas caurumu un izvediet tos piecus ķēniņus no alas pie manis.',
        23: 'Un tie tā darīja un izveda no tās alas pie viņa tos piecus ķēniņus, Jeruzālemes ķēniņu, Hebronas ķēniņu, Jarmutes ķēniņu, Lāķisas ķēniņu, Eglonas ķēniņu.',
        24: 'Un kad tie šos ķēniņus pie Jozuas bija izveduši, tad Jozuas sauca visus Israēla vīrus un sacīja uz tiem karavīru virsniekiem, kas viņam bija gājuši līdz: nākat klāt, liekat savas kājas uz šo ķēniņu kakliem, un tie piegāja un lika savas kājas uz viņu kakliem.',
        25: 'Un Jozuas uz tiem sacīja: nebīstaties un nebaiļojaties, esiet stipri un turat drošu prātu, jo tāpat Tas Kungs darīs visiem jūsu ienaidniekiem, ar ko jūs karojat.',
        26: 'Un pēc tam Jozuas viņus sita un nokāva, un pakāra pie pieciem kokiem, un tie palika pie kokiem pakārti līdz vakaram.',
        27: 'Un ap to laiku, kad saule noiet, Jozuas pavēlēja tos noņemt no tiem kokiem, un tie tos nometa tai alā, kur tie bija apslēpušies, un lika lielus akmeņus priekš tās alas cauruma, kas tur ir līdz šai dienai.',
        28: 'Tai dienā Jozuas arī uzņēma Maķedu, un to kāva ar zobena asmeni, un viņš izdeldēja viņas ķēniņu, viņu pašu un visas dvēseles, kas tur bija; viņš neatlicināja neviena, un darīja Maķedas ķēniņam tā kā viņš bija darījis Jērikus ķēniņam.',
        29: 'Tad Jozuas aizgāja un viss Israēls ar viņu no Maķedas uz Libnu un karoja pret Libnu.',
        30: 'Un Tas Kungs to arīdzan nodeva Israēla rokā ar viņas ķēniņu, un viņš to kāva ar zobena asmeni un visas dvēseles, kas tur bija, viņš neatlicināja iekš tās neviena, un darīja viņas ķēniņam, kā viņš bija darījis Jērikus ķēniņam.',
        31: 'Tad Jozuas aizgāja un viss Israēls ar viņu no Libnas līdz Lāķisai, un apmetās pret viņu un karoja pret viņu.',
        32: 'Un Tas Kungs nodeva Lāķisu Israēla rokā, un viņš to uzņēma otrā dienā un to kāva ar zobena asmeni, un visas dvēseles, kas tur bija; tā kā viņš Libnai bija darījis.',
        33: 'Tad Orams, Ģezeras ķēniņš, cēlās Lāķisai par palīgu, bet Jozuas to kāva un viņa ļaudis, kamēr viņš neviena no tiem neatlicināja.',
        34: 'Un Jozuas aizgāja un viss Israēls līdz ar viņu no Lāķisas uz Eglonu, un apmetās pret viņu un karoja pret viņu.',
        35: 'Un uzņēma viņu tai pašā dienā, un to kāva ar zobena asmeni, un visas dvēseles, kas tur bija, viņš tai dienā izdeldēja, kā viņš bija darījis Lāķisai.',
        36: 'Tad Jozuas cēlās un viss Israēls līdz ar viņu no Eglonas līdz Hebronei un karoja pret viņu,',
        37: 'Un uzņēma viņu un kāva viņu ar zobena asmeni un viņas ķēniņu ar visām pilsētām un ar visām dvēselēm, kas tur bija; viņš neatlicināja neviena, kā viņš Eglonai bija darījis, un to izdeldēja ar visām dvēselēm, kas tur bija,',
        38: 'Tad Jozuas griezās atpakaļ un viss Israēls līdz ar viņu uz Debiru un karoja pret viņu,',
        39: 'Un uzņēma viņu un viņas ķēniņu un visas viņa pilsētas, un tos kāva ar zobena asmeni un izdeldēja visas dvēseles, kas tur bija; viņš neatlicināja neviena; itin kā viņš Hebronai bija darījis, tā viņš darīja Debirai un viņas ķēniņam, un itin kā viņš Libnai un viņas ķēniņam bija darījis.',
        40: 'Tā Jozuas apkāva visu to zemi, kalnus un dienasvidus zemi un ieleju un pakalnus ar visiem viņu ķēniņiem: viņš neatlicināja neviena un izdeldēja visu, kam bija dvaša, tā kā Tas Kungs, Israēla Dievs, bija pavēlējis.',
        41: 'Un Jozuas tos kāva no Kādeš Barneas līdz Gazai, arī visu Gošena zemi līdz Gibeonai.',
        42: 'Un Jozuas uzņēma visus šos ķēniņus un visu viņu zemi uz vienu reizi, jo Tas Kungs, Israēla Dievs, karoja par Israēli.',
        43: 'Tad Jozuas griezās atpakaļ un viss Israēls līdz ar viņu uz Gilgalas lēģeri.',
    },
    11: {
        1: 'Un notika, kad Jabins, Hacoras ķēniņš, to dzirdēja, tad viņš sūtīja pie Jobaba, Madonas ķēniņa, un pie Šimronas ķēniņa un pie Akšafas ķēniņa,',
        2: 'Un pie tiem ķēniņiem, kas pret ziemeļiem kalnos un tai klajumā pret dienvidiem no Ķinerot un ielejā un kas Navot Dora jūrmalā dzīvoja,',
        3: 'Pie Kanaāniešiem pret rītiem un vakariem un pie Amoriešiem un Hetiešiem un Fereziešiem un Jebusiešiem kalnos un pie Hiviešiem apakš Hermona, Micpas zemē.',
        4: 'Šie izgāja un visi karapulki līdz ar tiem un daudz ļaužu, tik daudz kā smiltis jūrmalā, un varen daudz zirgu un ratu.',
        5: 'Visi šie ķēniņi sapulcējās un nāca un kopā apmetās lēģerī pie Meroma ūdens, karot pret Israēli.',
        6: 'Un Tas Kungs sacīja uz Jozua: nebīsties no viņiem, jo rītu ap šo laiku Es tos visus nodošu apkautus Israēla priekšā; viņu zirgus tev būs darīt tizlus un viņu ratus ar uguni sadedzināt.',
        7: 'Tad Jozuas un visi karaļaudis līdz ar viņu piepeši tiem uznāca pie Meroma ūdens un tiem uzbruka.',
        8: 'Un Tas Kungs tos nodeva Israēla rokā, un tie tos kāva un tiem dzinās pakaļ līdz tai lielai Sidonai un līdz tiem siltiem ūdeņiem un līdz Micpas klajumam pret rītiem un tos kāva, kamēr neviens no tiem neatlika.',
        9: 'Un Jozuas tiem darīja, kā Tas Kungs viņam bija sacījis; viņu zirgus viņš darīja tizlus un viņu ratus viņš sadedzināja ar uguni.',
        10: 'Un Jozuas griezās atpakaļ tanī laikā un uzņēma Hacoru, un viņas ķēniņu viņš sita ar zobenu, jo Hacora priekš tam bija galvas pilsēta visām šo ķēniņu valstīm.',
        11: 'Un tie kāva visus, kas tur bija, ar zobena asmeni, viņus izdeldēdami; tur neviens neatlika, kam bija dvaša, un Hacoru viņš sadedzināja ar uguni.',
        12: 'Un Jozuas uzņēma visas šo ķēniņu pilsētas un visus viņu ķēniņus un tos kāva ar zobena asmeni, tos izdeldēdams, kā Mozus, Tā Kunga kalps, bija pavēlējis.',
        13: 'Bet visas pilsētas, kas stāv savos kalnos, Israēls nesadedzināja, tikai Hacoru Jozuas sadedzināja.',
        14: 'Un visu šo pilsētu laupījumu un visus lopus Israēla bērni laupīja priekš sevis, bet visus cilvēkus tie kāva ar zobena asmeni, tiekams tie tos izdeldēja; tie neatlicināja neviena, kam bija dvaša.',
        15: 'Tā kā Tas Kungs Mozum, savam kalpam, bija pavēlējis, tā Mozus pavēlēja Jozuam, un tā Jozuas darīja; viņš neatrāva ne vārda no visa, ko Tas Kungs Mozum bija pavēlējis.',
        16: 'Tā Jozuas uzņēma visu šo zemi, kalnus un visu dienasvidus zemi un visu Gošenes zemi un ieleju un klajumu un Israēla kalnus ar viņu ieleju,',
        17: 'No Ālaka kalna, kas uz augšu stiepjas uz Seīru līdz Baāl-Gadam Lībanus klajumā, apakš Hermona kalna; viņš gūstīja arī visus viņu ķēniņus, tos sita un nokāva.',
        18: 'Ilgu laiku Jozuas pret visiem šiem ķēniņiem karoja.',
        19: 'Nevienas pilsētas nebija, kas ar labu Israēlim būtu padevusies, kā vien tie Hivieši, kas Gibeonā dzīvoja. Viņi visas uzņēma ar karošanu.',
        20: 'Jo tas bija no Tā Kunga, ka tie savu sirdi apcietināja, karā iet pret Israēli, lai Viņš tos izdeldētu, lai tiem nekāda žēlastība nenotiktu, bet lai Viņš tos nomaitātu, kā Tas Kungs Mozum bija pavēlējis.',
        21: 'Tanī laikā Jozuas nāca un izsakņoja Enaķiešus no tiem kalniem, no Hebronas, no Debiras, no Ānabas, no visiem Jūda kalniem un no visiem Israēla kalniem, un Jozuas tos izdeldēja ar viņu pilsētām.',
        22: 'Neviens no Enaķiešiem neatlika Israēla bērnu zemē, tik vien Gazā, Gatā un Ašdodā tie atlika.',
        23: 'Tā Jozuas uzņēma visu to zemi, tā kā Tas Kungs uz Mozu bija runājis, un Jozuas to Israēlim nodeva par iemantojamu tiesu, to dalīdams pēc viņu ciltīm, un zemei tika miers no karošanas.',
    },
    12: {
        1: 'Šie nu ir tās zemes ķēniņi, ko Israēla bērni ir kāvuši un viņu zemi ieņēmuši, viņpus Jardānes pret saules uzlēkšanu no Arnonas upes līdz Hermona kalnam un visu klajumu pret rītiem:',
        2: 'Sihons, Amoriešu ķēniņš, kas Hešbonā dzīvoja, valdīdams no Aroēra, kas Arnonas upes malā, un no tās upes vidus, un par vienu Gileādas pusi un līdz Jabokas upei, kas ir Amona bērnu robeža,',
        3: 'Un par to klajumu līdz Ķinerotes jūrai pret rītiem, un līdz tai klajuma jūrai, tai sāls jūrai pret rītiem, uz to ceļu līdz BetJezimotam, un dienvidu pusē apakš Pizgas kalna.',
        4: 'Un Oga, Basanas ķēniņa, robežas; tas bija atlicis no tiem milžu ļaudīm, un dzīvoja Astarotā un Edrejā,',
        5: 'Un valdīja par Hermona kalnu un par Zalku un par visu Basanu līdz Gešuriešu un Maāhatiešu robežām un tai vienā Gileādas pusē līdz Sihona, Hešbonas ķēniņa, robežām.',
        6: 'Mozus, Tā Kunga kalps, un Israēla bērni tos kāva, un Mozus, Tā Kunga kalps, to deva Rūbeniešiem un Gadiešiem un Manasus pusciltij par daļu.',
        7: 'Šie nu ir tās zemes ķēniņi, ko Jozuas un Israēla bērni kāva šaipus Jardānes pret vakariem, no Baāl-Gada Lībanus lejā līdz Ālaka kalnam, kas uz Seīru stiepjas, (un Jozuas to deva Israēla ciltīm par īpašumu pēc viņu daļām,)',
        8: 'Kalnos un ielejās un klajumos un pakalnos un tuksnesī un pret dienasvidu: Hetieši, Amorieši, Kanaānieši, Ferezieši, Hivieši un Jebusieši.',
        9: 'Jērikus ķēniņš viens; Ajas ķēniņš, kas sānis Bētelei, viens;',
        10: 'Jeruzālemes ķēniņš viens; Hebrones ķēniņš viens;',
        11: 'Jarmutes ķēniņš viens; Lākisas ķēniņš viens;',
        12: 'Eglonas ķēniņš viens; Ģezeras ķēniņš viens;',
        13: 'Debiras ķēniņš viens; Ģederas ķēniņš viens;',
        14: 'Hormas ķēniņš viens; Aradas ķēniņš viens;',
        15: 'Libnas ķēniņš viens; Adulamas ķēniņš viens;',
        16: 'Maķedas ķēniņš viens; Bēteles ķēniņš viens;',
        17: 'Tapuas ķēniņš viens; Heferas ķēniņš viens;',
        18: 'Afekas ķēniņš viens; LāŠaronas ķēniņš viens;',
        19: 'Madonas ķēniņš viens; Hacoras ķēniņš viens;',
        20: 'Šimron-Meronas ķēniņš viens; Akšafas ķēniņš viens;',
        21: 'Taēnakas ķēniņš viens; Meģidus ķēniņš viens;',
        22: 'Kēdesas ķēniņš viens; Jokneamas ķēniņš pie Karmeļa viens;',
        23: 'Doras ķēniņš Navat-Dorā viens; Gojimu ķēniņš Gilgalā viens;',
        24: 'Tircas ķēniņš viens; visi šie ķēniņi ir trīsdesmit un viens.',
    },
    13: {
        1: 'Un Jozuas bija vecs un stipri gados un Tas Kungs sacīja uz viņu: tu esi palicis vecs un stipri gados, un vēl ļoti daudz zemes atliek kas jāuzņem.',
        2: 'Šī ir tā zeme, kas vēl atliek: visas Fīlistu robežas un visas Gešuriešu robežas,',
        3: 'No Šihora, kas ir Ēģiptes priekšā, līdz Ekronas robežai pret ziemeļiem Kanaāniešiem top pieskaitīti pieci Fīlistu lielkungi: Gaziešu, Ašdodešu, Askaloniešu, Gatiešu un Ekroniešu lielskungs, un arī Avieši;',
        4: 'No dienasvidus puses visa Kanaāniešu zeme un Meara, kas Sidoniešiem pieder, līdz Afekai, līdz Amoriešu robežām;',
        5: 'Tā arī Ģibliešu zeme un viss Lībanus no rīta puses, no Baāl-Gada apakš Hermona kalna, kamēr nāk uz Hamatu;',
        6: 'Visi, kas tais kalnos dzīvo, no Lībanus līdz tiem siltiem ūdeņiem, visi Sidonieši, Es tos izdzīšu Israēla bērnu priekšā; izdali to tikai Israēlim par īpašumu, kā Es tev esmu pavēlējis.',
        7: 'Un nu dali šo zemi par iemantojamu tiesu tām deviņām ciltīm un Manasus pusciltij.',
        8: 'Līdz ar to (otru puscilti) Rūbenieši un Gadieši ir dabūjuši savu iemantojamo tiesu, ko tiem Mozus deva viņpus Jardānes pret rītiem, tā kā Mozus, Tā Kunga kalps, tiem devis,',
        9: 'No Aroēra, kas ir Arnonas upes malā, un tās pilsētas kas ir upes ielejas vidū, un visu klajumu no Medbas līdz Dibonai,',
        10: 'Un līdz Amona bērnu robežām visas pilsētas, kas piederēja Sihonam, Amoriešu ķēniņam, Hešbonas valdniekam,',
        11: 'Un Gileādu un Gešuriešu un Maāhatiešu robežas, un visu Hermona kalnu un visu Basanu līdz Zalkai,',
        12: 'Visu Oga, Basanas ķēniņa, valsti, kas valdīja Astarotā un Edrejā, un bija atlicis no tiem atlikušiem milžiem, ko Mozus ir apkāvis un izdzinis.',
        13: 'Bet Israēla bērni neizdzina Gešuriešus un Maāhatiešus, bet Gešurs un Maāhats dzīvoja Israēla vidū līdz šai dienai. -',
        14: 'Tikai Levja ciltij viņš nedeva zemes daļu; Tā Kunga, Israēla Dieva, uguns upuri ir viņas daļa, tā kā viņš tai ir runājis.',
        15: 'Un Mozus deva Rūbena bērnu ciltij pēc viņas radiem,',
        16: 'Ka viņu robežas bija no Aroēra, kas Arnonas upes malā, un tā pilsēta, kas ir ielejas vidū, un viss klajums līdz Medbai,',
        17: 'Hešbona un visas viņas pilsētas kas tai klajumā, Dibona un Bamot-Baāla un Bet-Baāl-Meona,',
        18: 'Un Jāca un Ķedemote un Mevaāte',
        19: 'Un Kiriataīma un Sibma un Ceret-Zaūra uz tā kalna tai ielejā.',
        20: 'Un Bet-Peore un Ašdod-Pizga un Bet-Jezimote',
        21: 'Un visas klajuma pilsētas un visa Sihona valsts, Sihona, Amoriešu ķēniņa, kas Hešbonā valdīja, ko Mozus apkāva līdz ar Midijanas lieliem kungiem, Evu un Reķimu un Curu un Huru un Rebu, Sihona valdniekiem, kas tai zemē dzīvoja.',
        22: 'Tāpat Israēla bērni ar zobenu nokāva Bileāmu, Beora dēlu, to pareģi, līdz ar tiem (citiem), ko viņi nokāva.',
        23: 'Un Rūbena bērnu robeža bija Jardāne un viņas apgabals. Šī ir Rūbena bērnu daļa pēc viņu radiem, pilsētas un viņu ciemi.',
        24: 'Un Gada ciltij, Gada bērniem pēc viņu radiem Mozus deva,',
        25: 'Ka viņu robežas bija Jaēzere un visas Gileādas pilsētas un Amona bērnu zemes viena puse līdz Aroēram, kas ir šaipus Rabas.',
        26: 'Un no Hešbonas līdz Rāmat-Micpai un Betanim un no Mahānaīm līdz Debiras robežai,',
        27: 'Un ielejā: BetHarama un Bet-Nimra un Sukota un Cavana, kas atlika no Sihona, Hešbonas ķēniņa, valsts, Jardāne un viņas robeža, līdz Ķinerotes jūras galam viņpus Jardānes pret rītiem.',
        28: 'Šī ir Gada bērnu daļa pēc viņu radiem, pilsētas un ciemi.',
        29: 'Un ko Mozus Manasus pusciltij par daļu bija devis, tas palika pie Manasus bērnu puscilts pēc viņas radiem,',
        30: 'Tā ka viņu robežas bija no Mahānaīm visa Basana, visa Oga, Basanas ķēniņa, valsts un visi Jaīra miesti, kas ir Basanā, sešdesmit pilsētas.',
        31: 'Un Gileādas viena puse un Astarote un Edreja, Oga, Basanas ķēniņa, valsts pilsētas, piederēja Mahira, Manasus dēla, bērniem, (proti) Mahira bērnu pusei pēc viņu radiem.',
        32: 'To nu Mozus bija izdalījis Moaba klajumos viņpus Jardānes no Jērikus pret rītiem.',
        33: 'Bet Levja ciltij Mozus nedeva nekādu zemes daļu; Tas Kungs, Israēla Dievs, ir viņu daļa, tā kā Viņš tiem ir runājis.',
    },
    14: {
        1: 'To nu Israēla bērni iemantojuši Kanaāna zemē, ko viņiem ir izdalījuši Eleazars, tas priesteris, un Jozuas, Nuna dēls, un tie augstie Israēla bērnu cilts tēvi.',
        2: 'Caur meslošanu tiem dalīja, kā Tas Kungs caur Mozu bija pavēlējis, dot tām deviņām ciltīm un tai pusciltij.',
        3: 'Jo tām divām ciltīm un tai pusciltij Mozus bija devis daļu viņpus Jardānes, bet Levitiem viņš nekādu zemes daļu nebija devis viņu starpā.',
        4: 'Jo Jāzepa bērnu bija divas ciltis, Manasus un Efraīms; un Levitiem nedeva nekādu īpašu daļu tai zemē, bet pilsētas vien, kur dzīvot, un ganības priekš viņu lopiem un priekš viņu īpašuma.',
        5: 'Kā Tas Kungs Mozum bija pavēlējis, tā Israēla bērni darīja un izdalīja to zemi.',
        6: 'Tad Jūda bērni piegāja pie Jozuas Gilgalā, un Kālebs, Jefunna dēls, no Ķenasa bērniem, sacīja uz viņu: tu zini to vārdu, ko Tas Kungs uz Mozu, to Dieva vīru, ir runājis Kādeš Barneā manis pēc un tevis pēc.',
        7: 'Es biju četrdesmit gadus vecs, kad Mozus, Tā Kunga kalps, mani sūtīja no Kādeš Barneas, to zemi izlūkot, un es viņam atsacīju, tā kā tas bija manā sirdī.',
        8: 'Bet mani brāļi, kas man bija gājuši līdz, tie darīja to ļaužu sirdi bailīgu, bet es Tam Kungam, savam Dievam, pareizi klausīju.',
        9: 'Tad Mozus tai dienā zvērēja un sacīja: tā zeme, kur tu ar savu kāju esi minis, tev un taviem bērniem būs par daļu mūžam; jo tu Tam Kungam, manam Dievam, esi pareizi klausījis.',
        10: 'Un nu redzi, Tas Kungs manu dzīvību ir uzturējis, tā kā Viņš ir runājis, un ir četrdesmit un pieci gadi no tā laika, kad Tas Kungs šo vārdu uz Mozu runāja, Israēlim tuksnesī staigājot, un nu redzi, es šodien esmu astoņdesmit piecus gadus vecs.',
        11: 'Es vēl šodien esmu tik stiprs, kā tai dienā kad Mozus mani izsūtīja; kāds mans spēks bija to brīdi, tāds ir mans spēks šo brīdi uz karu, uz iziešanu un ieiešanu.',
        12: 'Un nu, dod man šo kalnu zemi, par ko Tas Kungs tai dienā runājis, jo tu tai dienā esi dzirdējis, ka tur dzīvo Enaķieši, un tur ir lielas stipras pilsētas; varbūt Tas Kungs būs ar mani, ka es tos varu izdzīt, tā kā Tas Kungs runājis.',
        13: 'Tad Jozuas viņu svētīja un deva Kālebam, Jefunna dēlam, Hebroni par daļu.',
        14: 'Tā tad Hebrone Kālebam, Jefunna dēlam, no Ķenasa bērniem, tika par daļu līdz šai dienai, tāpēc ka tas Tam Kungam, Israēla Dievam, pareizi bija klausījis.',
        15: 'Bet Hebrones vārds bija vecos laikos Kiriat Arba (Arbas pilsēta), tas ir bijis viens liels cilvēks starp Enaķiešiem. Un zemei bija miers no karošanas.',
    },
    15: {
        1: 'Un tā nomeslota tiesa priekš Jūda bērniem, pēc viņu radiem, bija pie Edoma robežām, pie Cin tuksneša, pašā dienvidus galā,',
        2: 'Tā ka viņu robeža pret dienvidiem bija Sāls jūras gals no tās mēles, kas pret dienvidiem stiepjas,',
        3: 'Un iziet pret dienvidu pusi uz Akrabu kalniem un iet cauri līdz Cinam un iet uz augšu no dienvidu puses līdz Kādeš-Barneai,',
        4: 'Un iet caur Acronu un stiepjas uz augšu līdz Ādarai un iet ap Karku un iet cauri līdz Acmonai un iznāk pie Ēģiptes upes, un tas robežas gals stiepjas pret jūru; šī lai ir jūsu robeža dienas vidū.',
        5: 'Un robeža pret rītiem ir sāls jūra līdz Jardānes galam, un robeža ziemeļa pusē ir no jūras mēles, no Jardānes gala.',
        6: 'Un šī robeža iet uz augšu līdz Bet-Aglai un iet cauri no ziemeļa puses līdz Bet-Arabai, un tā robeža iet uz augšu līdz Boēna, Rūbena dēla, akmenim.',
        7: 'Un (tālāk) šī robeža iet uz augšu līdz Debirai no Ahora ielejas un pret ziemeļiem stiepjas līdz Gilgalai, kas stāv pret Adumu kalniem, kas no upes uz dienvidiem; pēc šī robeža iet cauri uz En-Zemes ūdeni, un viņas gals stiepjas līdz Roģeles akai.',
        8: 'Un šī robeža iet uz augšu pa Ben-Inoma ieleju, no dienvidu puses gar Jebuzu, - šī ir Jeruzāleme, - un šī robeža iet uz augšu līdz tā kalna virsgalam, kas no Inoma ielejas ir pret vakara pusi, kas stiepjas līdz Refaīm ielejas galam pret ziemeļiem.',
        9: 'Pēc šī robeža stiepjas no tā kalna gala līdz Nevtoas avotam un iznāk uz Efrona kalna pilsētām; šī robeža stiepjas līdz Baālai, - tā ir Kiriat-Jearima.',
        10: 'Pēc šī robeža griežas no Baālas uz vakara pusi līdz Seīra kalniem un iet cauri gar ArJearim uz ziemeļa pusi, - tas ir Ķesalons, - un nāk lejā uz Bet-Šemesu un iet caur Timnatu.',
        11: 'Un tā robeža iznāk gar Ekronu pret ziemeļa pusi un stiepjas līdz Zikronam un iet pār Baālas kalnu un iznāk uz Jabneēlu, un viņas gals stiepjas līdz jūrai.',
        12: 'Un robeža pret vakara pusi ir tā lielā jūra un viņas mala. Šī ir Jūda bērnu robeža visapkārt pēc viņu radiem.',
        13: 'Bet Kālebam, Jefunna dēlam, viņš deva tiesu starp Jūda bērniem, pēc Tā Kunga vārda uz Jozua, proti Kiriat-Arbu, Eneka tēva pilsētu, tā ir Hebrone.',
        14: 'Un Kālebs izdzina no turienes tos trīs Enaka dēlus, Zezaju un Aķimanu un Talmaju, kas no Enaka dzimuši.',
        15: 'Un no turienes viņš cēlās pret Debiras iedzīvotājiem, bet Debiras vārds senāk bija Kiriat-Zevere.',
        16: 'Un Kālebs sacīja: kas Kiriat-Zeveri kaus un uzņems, tam es savu meitu Aksu došu par sievu.',
        17: 'Tad to uzņēma Otniēls, Ķenasa dēls, Kāleba brālēns, un viņš tam deva savu meitu Aksu par sievu.',
        18: 'Un notikās, kad viņa pie tā nāca, tad viņa to skubināja, tīrumu lūgties no viņas tēva, un viņa nolēca no ēzeļa; tad Kālebs uz viņu sacīja: kas tev ir?',
        19: 'Un viņa sacīja: dod man kādu svētību, jo tu man esi devis dienvidu zemi, tad dod man arī ūdens avotus. Tad tas viņai deva avotus augšā un avotus ielejā.',
        20: 'Šī ir Jūda bērnu cilts daļa pēc viņu radiem.',
        21: 'Tad nu tās pilsētas no Jūda bērnu cilts gala līdz Edoma robežai pret dienvidu pusi ir: Kabceēle un Edere un Jagura',
        22: 'Un Ķina un Dimona un Ādada',
        23: 'Un Ķedesa un Ācora un Itnana',
        24: 'Un Zīva un Telema un Bealota',
        25: 'Un Ācor-ādāta un Kiriat-Hecrona, - tā ir Ācora, -',
        26: 'Āmama un Šema un Molada',
        27: 'Un Ācar Gada un Ezmona un Betpaleta',
        28: 'Un Ācar-Zuala un Bēršeba un Bisjot-Ja,',
        29: 'Bala un Ijim un Ācēma',
        30: 'Un Eldolada un Ķezila un Horma',
        31: 'Un Ciklaga un Madmana un Zan-Zana',
        32: 'Un Lebaota, Zilim un Aīna un Rimona, - visu šo pilsētu ir divdesmit deviņas un viņu ciemi.',
        33: 'Lejā ir Estaole un Carea un Asna',
        34: 'Un Zanoa un En-Ganim, Tapua un Enama',
        35: 'Un Jarmute un Adulama un Zukus un Āzeka',
        36: 'Un Zaēraīm un Aditaīm un Gedera un Ģederotaīm, četrpadsmit pilsētas un viņu ciemi;',
        37: 'Cenana un Adaza un Migdal Gada',
        38: 'Un Dileana un Micpa un Jaktiēle,',
        39: 'Lāķis un Bockata un Eglone',
        40: 'Un Kābona un Lāmasa un Ķitlisa',
        41: 'Un Ģederota, BetDagona un Naēma un Maķeda, sešpadsmit pilsētas un viņu ciemi;',
        42: 'Libna un Etere un Āzana',
        43: 'Un Jevta un Azna un Necibe',
        44: 'Un Ķeīla un Aksiba un Mareza, deviņas pilsētas un viņu ciemi;',
        45: 'Ekrona un viņas miesti un viņas ciemi;',
        46: 'No Ekronas un līdz jūrai viss, kas blakām Ašdodai un blakām viņu ciemiem;',
        47: 'Ašdoda un viņas miesti, un viņas ciemi, Gaza un viņas miesti, un viņas ciemi līdz Ēģiptes upei un tai lielai jūrai un viņas malai.',
        48: 'Un kalnos bija Zamira un Jatira un Zokus',
        49: 'Un Dana, un Kiriat-Zana, - tā ir Debira -',
        50: 'Un Ānaba un Estemus un Ānim',
        51: 'Un Gošene un Holone un Šīlo, vienpadsmit pilsētas un viņu ciemi;',
        52: 'Arāba un Duma un Ezeaņa un Januma.',
        53: 'Un Bet-Tapua un Āveka',
        54: 'Un Umta un Kiriat-Arba, - tā ir Hebrone, - un Ciora, deviņas pilsētas un viņu ciemi;',
        55: 'Maona, Karmelis un Zīva un Jūta',
        56: 'Un Jezreēle un Jokdeama un Zanoa,',
        57: 'Kaina, Ģibea un Timna, desmit pilsētas un viņu ciemi;',
        58: 'Alula, Bet-Cura, Gedora',
        59: 'Un Maārata un Bet-Anota un Eltekone, sešas pilsētas un viņu ciemi;',
        60: 'Kiriat-Baāla, - tā ir Kiriat-Jearima, - un Arāba, divas pilsētas un viņu ciemi.',
        61: 'Tuksnesī bija Bet-Araba, Midina un Zekaka.',
        62: 'Un Nibzana un tā sāls pilsēta un Enģedi, sešas pilsētas un viņu ciemi.',
        63: 'Bet tos Jebusiešus, kas Jeruzālemē dzīvoja, Jūda bērni nevarēja izdzīt un Jebusieši dzīvoja pie Jūda bērniem Jeruzālemē līdz šai dienai.',
    },
    16: {
        1: 'Un tā tiesa Jāzepa bērniem tapa nomeslota no Jardānes pret Jēriku, pie Jērikus ūdeņiem pret rītiem, tas tuksnesis, kas no Jērikus stiepjas caur Bēteles kalniem',
        2: 'Un iznāk no Bēteles uz Lūzu un tek caur Arķiešu robežām līdz Atarotai,',
        3: 'Un noiet pret vakara pusi uz Javletes robežām līdz Lejas-Bet-Oronas robežām un līdz Gazerai, un viņas gals stiepjas līdz jūrai.',
        4: 'Tā Jāzepa bērni, Manasus un Efraīms, savu daļu dabūjuši.',
        5: 'Un Efraīma bērnu robeža pēc viņu radiem ir šī: viņu daļas robeža bija pret rītiem Atarot Ādara līdz Kalna-Bet-Oronai.',
        6: 'Un tā robeža iznāk no vakara puses gar Miķmetu pa ziemeļa pusi, un šī robeža griežas pret rītiem uz Taēnat Šīlo un iet caur viņu uz rīta pusi līdz Janoai,',
        7: 'Un notek no Janoas uz Atarotu un Naāratu, un stiepjas uz Jēriku un iznāk pie Jardānes.',
        8: 'No Tapuas tā robeža stiepjas pret vakara pusi uz Kānas upi, un viņas gals ir pie jūras. Šī ir Efraīma bērnu cilts daļa pēc viņu radiem.',
        9: 'Un tās pilsētas, kas bija atšķirtas priekš Efraīma bērniem, bija Manasus bērnu daļas vidū, visas tās pilsētas un viņu ciemi.',
        10: 'Un tie neizdzina tos Kanaāniešus, kas Gazerā dzīvoja, tā Kanaānieši dzīvoja Efraīma vidū līdz šai dienai un palika par klausītājiem.',
    },
    17: {
        1: 'Un Manasus ciltij tiesa tika nomeslota, - jo viņš bija Jāzepa pirmdzimtais, - Mahiram, Manasus pirmdzimtam, Gileāda tēvam, kas bija karavīrs, krita Gileāda un Basana.',
        2: 'Un tiem citiem Manasus bērniem tika sava tiesa pēc viņu radiem, (proti) Abiēzera bērniem un Eleka bērniem un Asriēļa bērniem un Zeķema bērniem un Hefera bērniem un Zemida bērniem. Šie ir Manasus, Jāzepa dēla, bērni no vīriešu kārtas pēc saviem radiem.',
        3: 'Bet Celofehadam, Hefera dēlam, (tas bija dēls Gileādam, tas Mahiram, tas Manasum) tam nebija dēlu, bet meitas vien, un šie ir viņa meitu vārdi: Maāla, Noa, Hagla, Milka un Tirca.',
        4: 'Tās nāca pie priestera Eleazara un pie Jozuas, Nuna dēla, un pie tiem virsniekiem un sacīja: Tas Kungs Mozum pavēlējis, mums daļu dot mūsu brāļu vidū; tāpēc viņš pēc Tā Kunga vārda tām deva daļu viņu tēva brāļu vidū.',
        5: 'Un Manasum desmit zemes gabali tapa piedalīti, bez Gileādas zemes un Basanas, kas viņpus Jardānes.',
        6: 'Jo Manasus meitas iemantoja īpašu daļu viņa dēlu vidū, un Gileādas zeme piederēja tiem citiem Manasus bērniem.',
        7: 'Un Manasus robeža bija no Ašeras līdz Mikmetai, kas Šehemes priekša, un šī robeža iet pa labo roku uz tiem, kas En-Tapuā dzīvoja,',
        8: 'Un Manasum gan piederēja Tapuas zeme, bet pati Tapua pie Manasus robežas piederēja Efraīma bērniem.',
        9: 'Un tā robeža nonāk uz Kānas upi pret dienasvidu no upes. Šīs pilsētas pieder Efraīmam, Manasus pilsētu vidū, un Manasus robeža ir no tās upes uz ziemeļa pusi, un viņas gals stiepjas pret jūru.',
        10: 'Kas pret dienvidiem, pieder Efraīmam, un kas pret ziemeļiem, Manasum, un jūra ir viņu robeža. Un uz ziemeļa pusi viņi stiepjas līdz Ašeram, un uz rīta pusi līdz Īsašaram.',
        11: 'Un Manasum iekš Īsašara un Ašera piederēja Bet-Zeana un viņas miesti un Jibleana un viņas miesti un Doras iedzīvotāji un miesti un Endoras iedzīvotāji un miesti un Taēnakas iedzīvotāji un miesti un, kas iekš Meģidus dzīvoja, un viņa miesti, - trīs zemes gabali',
        12: 'Un Manasus bērni nevarēja izdzīt šo pilsētu iedzīvotājus, bet Kanaānieši iesāka palikt tai zemē.',
        13: 'Un kad Israēla bērni palika stipri, tad tie tos Kanaāniešus spieda pie klausības, bet izdzīt tos neizdzina.',
        14: 'Un Jāzepa bērni runāja uz Jozua sacīdami: kāpēc tu mums par daļu esi nomeslojis tikai vienu tiesu un vienu zemes gabalu? Un mēs tomēr esam liels ļaužu pulks, tādēļ ka Tas Kungs mūs tā ir svētījis.',
        15: 'Tad Jozuas uz tiem sacīja: ja jūs esiet tāds liels ļaužu pulks, tad ejat mežos un nolīdiet tos priekš sevis Veresiešu un Revaiešu zemē, kad jums nepietiek ar Efraīma kalniem,',
        16: 'Tad Jāzepa bērni sacīja: ar tiem kalniem mums nepietiks, un dzelzs rati ir visiem Kanaāniešiem, kas tai ielejas zemē dzīvo, Bet-Zeanā un viņas miestos, un tiem, kas Israēla klajumā dzīvo.',
        17: 'Bet Jozuas runāja uz Jāzepa namu, uz Efraīmu un Manasu, sacīdams: tu esi liels ļaužu pulks un tev ir liels spēks, tev nebūs viena daļa vien,',
        18: 'Bet tie kalni tev piederēs; tur ir mežs un to tu nolīdisi un viņa malas tev piederēs. Jo tu izdzīsi tos Kanaāniešus, jebšu tiem ir dzelzs rati un jebšu tie ir stipri.',
    },
    18: {
        1: 'Un visa Israēla bērnu draudze sapulcējās Šīlo un tur uzcēla saiešanas telti, kad nu zeme viņu priekšā bija uzvarēta.',
        2: 'Un no Israēla bērniem, kam savas daļas nebija nodalītas, atlika septiņas ciltis.',
        3: 'Un Jozuas sacīja uz Israēla bērniem: cik ilgi jūs esat tik kūtri, ka nenoejat uzņemt to zemi, ko Tas Kungs, jūsu tēvu Dievs jums devis?',
        4: 'Dabūjiet sev trīs vīrus no ikvienas cilts, tad es tos sūtīšu, lai tie ceļas un zemi pārstaigā un to uzraksta pēc savām daļām, un griežas atpakaļ pie manis.',
        5: 'Tiem nu to būs dalīt septiņās daļās; Jūda lai paliek savās robežās no dienasvidus puses, un Jāzepa nams lai paliek savās robežās no ziemeļa puses.',
        6: 'Un jums to zemi būs uzrakstīt septiņās daļās un atnest man, ka es priekš jums šeit mesloju Tā Kunga, mūsu Dieva, priekšā.',
        7: 'Jo Levitiem nav nekādas zemes daļas jūsu starpā, bet Tā Kunga priestera amats ir viņu daļa. Bet Gads un Rūbens un Manasus puscilts savu tiesu ir ņēmuši viņpus Jardānes pret rītiem, ko Mozus, Tā Kunga kalps, tiem devis.',
        8: 'Tad tie vīri cēlās un nogāja, un Jozuas tiem, kas nogāja, pavēlēja zemi uzrakstīt, un sacīja: ejat, un pārstaigājat to zemi un uzrakstiet to un griežaties atpakaļ pie manis, tad es priekš jums metīšu meslus Tā Kunga priekšā šeitan Šīlo.',
        9: 'Tad tie vīri nogāja un pārstaigāja to zemi un to pēc viņas pilsētām grāmatā uzrakstīja septiņās daļās, un nāca atpakaļ pie Jozuas uz lēģeri Šīlo.',
        10: 'Un Jozuas meta meslus priekš viņiem Šīlo Tā Kunga priekšā, un Jozuas tur Israēla bērniem dalīja to zemi pēc viņu daļām.',
        11: 'Un mesli krita Benjamina bērnu ciltij pēc viņu radiem, un viņu nomeslotās tiesas robeža stiepjas starp Jūda bērniem un Jāzepa bērniem.',
        12: 'Un viņu ziemeļa robeža nāca no Jardānes, un šī robeža iet augšā gar Jērikus ziemeļa pusi un stiepjas caur tiem kalniem pret vakara pusi un viņas gals ir pie Bet-Avenas tuksneša.',
        13: 'Un no turienes robeža aiziet uz Lūzu, gar Lūzu, - šī ir Bētele, - pret dienasvidu, un robeža noiet uz Atarot-Ādaru pie tā kalna, kas ir dienasvidus pusē no Lejas-Bet-Oronas.',
        14: 'Un šī robeža stiepjas un griežas vakara malā uz dienasvidu, no tā kalna, kas ir Bet-Oronai pretī uz dienasvidu, un viņas gals ir pie Kiriat-Baālas, - šī ir Kiriat-Jearima, Jūda bērnu pilsēta, - šī ir vakara puses mala.',
        15: 'Un dienasvidus mala stiepjas no Kiriat-Jearimas gala, un šī robeža iznāk no vakara puses un iziet uz Nevtoas avotu.',
        16: 'Un šī robeža noiet līdz tā kalna galam, kas ir Inoma dēla ielejai pretī, Revaiešu ielejā pret ziemeļiem un noiet caur Inoma ieleju gar Jebusiešiem pret dienasvidu un noiet līdz Roģeles avotam,',
        17: 'Un stiepjas uz ziemeļa pusi un iznāk uz En-Zemesu un iziet uz Ģililotu, kas stiepjas pret Adumim, un noiet uz Boēna, Rūbena dēla, akmeni,',
        18: 'Un iet pāri gar to klajumu uz ziemeļa pusi un noiet uz to klajumu.',
        19: 'Un šī robeža iet pāri gar Bet-Aglu pret ziemeļiem, un šās robežas gals ir pie sāls jūras mēles pret ziemeļiem, pie Jardānes gala dienas vidū; šī ir dienvidu robeža.',
        20: 'Un Jardāne ir viņa robeža rīta pusē; šī ir Benjamina bērnu daļa pēc viņu robežām visapkārt, pēc viņu radiem.',
        21: 'Bet Benjamina bērnu cilts pilsētas pēc viņu radiem ir: Jērikus un Bet-Agla un Emek-Ķecica',
        22: 'Un Bet-Araba un Cemaraīm un Bētele.',
        23: 'Un Avim un Para un Ovra',
        24: 'Un Kavar-Amonaja un Ovni un Gaba, divpadsmit pilsētas un viņu ciemi;',
        25: 'Gibeona un Rāma un Beērote',
        26: 'Un Micpa un Ķevira un Moca',
        27: 'Un Reķeme un Jerpeēle un Tareala',
        28: 'Un Cela, Eleve un Jebuzi, - šī ir Jeruzāleme, - Ģibeata, Kiriata, četrpadsmit pilsētas un viņu ciemi. Šī ir Benjamina bērnu daļa pēc viņu radiem.',
    },
    19: {
        1: 'Un otri mesli krita Sīmeanam, Sīmeana bērnu ciltij pēc viņu radiem, un viņu nomeslota tiesa bija Jūda bērnu starpā.',
        2: 'Un tiem bija par daļu: Bēršeba un Zeba un Moloda',
        3: 'Un Hacar-Šuale un Bala un Aceme',
        4: 'Un Eltolade un Betule un Horma',
        5: 'Un Ciklaga un Bet-Markabote un Acar-Zusa',
        6: 'Un Betlebaote un Zaruēne, trīspadsmit pilsētas un viņu ciemi;',
        7: 'Aīna, Rimona un Etere un Azane, četras pilsētas un viņu ciemi,',
        8: 'Un visi ciemi šo pilsētu apgabalā līdz Baālat-Beērei, dienasvidus Rāmatai; šī ir Sīmeana bērnu cilts daļa pēc viņu radiem.',
        9: 'Sīmeana bērnu daļa ir Jūda bērnu zemē, jo Jūda bērnu tiesa tiem bija par lielu, tāpēc Sīmeana bērni mantoja viņu daļas vidū.',
        10: 'Un trešie mesli krita Zebulona bērniem pēc viņu radiem, un viņu daļas robeža stiepjas līdz Zaridei.',
        11: 'Un viņu robeža iet uz augšu pret vakara pusi uz Marealu, un tek līdz Dabazetei un stiepjas līdz tai upei, kas šaipus Jokneama.',
        12: 'Un viņa griežas no Zarides pret rītiem pret saules lēkšanu, uz Ķislot-Tābora robežām, un iznāk pie Dobrates un stiepjas līdz Javiai;',
        13: 'Un no turienes viņa iet pret rītiem, pret saules lēkšanu, uz GatEveru, Iti, Kacini un iznāk pie Rimona, sniegdamās līdz Neai.',
        14: 'Un šī robeža griežas apkārt pret ziemeļa pusi uz Kanatonu, un viņas gals ir Jevtaēles ieleja.',
        15: 'Un Katāte un Nahāle un Šimrona un Jedeala un Bētleme, divpadsmit pilsētas un viņu ciemi.',
        16: 'Šī ir Zebulona bērnu daļa pēc viņu radiem, šīs pilsētas un viņu ciemi.',
        17: 'Ceturtie mesli krita Īsašaram, Īsašara bērniem pēc viņu radiem.',
        18: 'Un viņu robežas bija Jezreēls, Ķezulote un Šuneme.',
        19: 'Un Avaraīm un Sihons un Anaārot',
        20: 'Un Rabita un Ķiseons un Abeca',
        21: 'Un Remeta un Enganim un Enada un Bet-Paceca.',
        22: 'Un šī robeža stiepjas un Tāboru un Zaācimu un Bet-Šemesu un viņu robežas gals ir pie Jardānes: sešpadsmit pilsētas un viņu ciemi.',
        23: 'Šī ir Īsašara bērnu cilts daļa, pēc viņu radiem, pilsētas un viņu ciemi.',
        24: 'Un piektie mesli krita Ašera bērniem pēc viņu radiem.',
        25: 'Un viņu robežas bija Elkate un Alus un Betene un Aksave',
        26: 'Un Alameleķs un Ameada un Mizeala, un stiepjas uz Karmeli pie jūras un uz Šihor-Libnatu,',
        27: 'Un griežas pret saules lēkšanu uz Bet-Dagonu un stiepjas uz Zebulonu un uz JevtaEles ieleju pret ziemeļiem no Bet-Emeka un Neģiēla un iznāk uz Kabalu pa kreiso roku,',
        28: 'Un uz Hebronu un Reobu un Amonu un Kānu līdz lielai Sidonai.',
        29: 'Un šī robeža griežas uz Ramu un uz stipro Tirus pilsētu, tad šī robeža griežas uz Osu, un viņas gals ir pie jūras, blakām Aksibes robežām.',
        30: 'Un Umma un Afeks un Reobe: divdesmit divas pilsētas un viņu ciemi.',
        31: 'Šī ir Ašera bērnu cilts daļa pēc viņu radiem, šīs pilsētas un viņu ciemi.',
        32: 'Sestie mesli krita Naftalus bērniem pēc viņu radiem.',
        33: 'Un viņu robeža ir no Eleves, no tā ozola pie Caēnanim, un Adami-Neķebes un Jabneēļa līdz Lakum, un viņas gals ir pie Jardānes.',
        34: 'Un šī robeža griežas pret vakara pusi uz Asnot-Tāboru, un no turienes viņa noiet uz Ukoku, un stiepjas uz Zebulonu pret dienasvidu, un pie Ašera viņa stiepjas pret vakara pusi, un pie Jūda līdz Jardānei pret saules lēkšanu.',
        35: 'Un stipras pilsētas ir: Cidim, Cera un Amata, Rākata un Ķinerete',
        36: 'Un Ādama un Rāma un Hacore',
        37: 'Un Ķedesa un Edreji un EnAcore',
        38: 'Un Jereons un MigdalEle, Oreme un Bet-Anata un BetŠemes, deviņpadsmit pilsētas un viņu ciemi.',
        39: 'Šī ir Naftalus bērnu cilts daļa pēc viņu radiem, pilsētas un viņu ciemi.',
        40: 'Septītie mesli krita Dana bērnu ciltij pēc viņu radiem.',
        41: 'Un viņu daļas robežas bija Carea un Estaole un Irzameze',
        42: 'Un Zaēlabina un Ajalone un Jetla.',
        43: 'Un Elona un Timnata un Ekrona',
        44: 'Un Elteķe un Ģibetonā un Baālate,',
        45: 'Jeūde un Bne-Barata un Gat-Rimona,',
        46: 'Un Mejarkona un Rakona, ar to robežu pret Joppi.',
        47: 'Bet Dana bērnu robežas kļuva lielākas, jo Dana bērni cēlās un karoja pret Lezemu un to uzņēma un to sita ar zobena asmeni un to iemantoja un tur dzīvoja, un nosauca Lezemu par Danu pēc sava tēva Dana vārda.',
        48: 'Šī ir Dana bērnu cilts daļa pēc viņu radiem, pilsētas un viņu ciemi.',
        49: 'Un kad tie nu bija beiguši zemi izdalīt pēc viņas robežām, tad Israēla bērni Jozuam, Nuna dēlam, deva daļu savā vidū.',
        50: 'Pēc Tā Kunga vārda tie viņam deva to pilsētu, ko viņš prasīja, Timnat-Zeru Efraīma kalnos, un viņš uztaisīja to pilsētu un tur dzīvoja.',
        51: 'Tās ir tās daļas, ko priesteris Eleazars, un Jozuas, Nuna dēls, un tie cilts tēvi Israēla bērnu ciltīm caur mesliem izdalīja Šīlo Tā Kunga priekšā pie saiešanas telts durvīm un tā tie pabeidza zemes izdalīšanu.',
    },
    20: {
        1: 'Un Tas Kungs runāja uz Jozua un sacīja:',
        2: 'Runā uz Israēla bērniem un saki: noliekat sev glābšanās pilsētas, par kurām Es uz jums esmu runājis caur Mozu,',
        3: 'Ka uz turieni var bēgt tas nokāvējs, kas kādu dvēseli no nejauši nezinādams nokauj, ka tās jums var būt par patvēruma no asins atriebēja.',
        4: 'Un kurš uz kādu no šīm pilsētām bēg, tam pie pilsētas vārtiem būs stāvēt, un savus vārdus runāt priekš pilsētas vecaju ausīm; tad tie viņu lai uzņem pie sevis pilsētā un viņam dod vietu, ka viņš pie tiem var dzīvot.',
        5: 'Un kad tas asins atriebējs viņam dzenās pakaļ, tad lai tie to nokāvēju viņam nedod rokā, tāpēc ka viņš nezinādams savu tuvāko nokāvis, un viņu iepriekš nav ienīdējis.',
        6: 'Tad tam tai pilsētā būs dzīvot, tiekams viņš draudzes priekšā būs stāvējis uz tiesu, līdz kamēr tas augstais priesteris būs miris, kas tanīs dienās būs, tad lai tas nokāvējs griežas atpakaļ un iet savā pilsētā un savā namā, tai pilsētā, no kurienes viņš izbēdzis.',
        7: 'Tad tie iesvētīja Ķedesu Galilejā Naftalus kalnos, un Šehemi Efraīma kalnos, un ĶniatArpu, - tā ir Hebrone, - Jūda kalnos.',
        8: 'Un viņpus Jardānes, no Jērikus pret rītiem, tie deva Beceru tuksnesi Rūbena cilts klajumā, un Golanu Basanā no Manasus cilts.',
        9: 'Šīs tās noliktās pilsētas priekš visiem Israēla bērniem un priekš svešiniekiem viņu starpā, ka uz turieni bēgtu ikkatrs, kas cilvēku nejauši nokauj, ka tam nebūtu jāmirst caur asins atriebēja roku, pirms nebūtu stāvējis draudzes priekšā.',
    },
    21: {
        1: 'Tad Levitu cilts tēvi piegāja pie priestera Eleazara un pie Jozuas, Nuna dēla, un pie Israēla bērnu cilts tēviem,',
        2: 'Un runāja uz tiem Šīlo Kanaāna zemē, sacīdami: Tas Kungs caur Mozu pavēlējis, mums dot pilsētas, kur varam dzīvot, ar ganībām priekš mūsu lopiem.',
        3: 'Tad Israēla bērni Levitiem deva no savām daļām pēc Tā Kunga vārda šīs pilsētas un viņu ganības.',
        4: 'Un mesli krita Kehāta radiem. Un priestera Ārona bērniem no Levitiem caur mesliem krita trīspadsmit pilsētas no Jūda cilts un no Sīmeana cilts un no Benjamina cilts.',
        5: 'Un tiem citiem Kehāta bērniem caur mesliem krita desmit pilsētas no Efraīma cilts radiem un no Dana cilts un no Manasus puscilts.',
        6: 'Un Geršona bērniem caur mesliem krita trīspadsmit pilsētas no Īsašara cilts radiem un no Ašera cilts un no Naftalus cilts un no Manasus puscilts Basanā.',
        7: 'Merarus bērniem pēc viņu radiem krita divpadsmit pilsētas no Rūbena cilts un no Gada cilts un no Zebulona cilts.',
        8: 'Tā Israēla bērni Levitiem deva caur meslošanu šīs pilsētas un viņu ganības, kā Tas Kungs caur Mozu bija pavēlējis.',
        9: 'Un no Jūda bērnu cilts un no Sīmeana bērnu cilts tie deva šīs pilsētas, ko pie vārda nosauca,',
        10: 'Ka tie piederētu Ārona bērnu bērniem, no Kehāta radiem, no Levja bērniem; jo tie pirmie mesli viņiem krita.',
        11: 'Un tie tiem deva Kiriat-Arbu, Enaka tēva pilsētu, tā ir Hebrone Jūda kalnos un viņas apkārtējās ganības.',
        12: 'Bet tās pilsētas tīrumu un līdz ar viņas ciemiem tie deva Kālebam, Jefunna dēlam, par dzimtu.',
        13: 'Un tie deva priestera Ārona bērniem to glābšanas pilsētu priekš nokāvējiem, Hebroni un viņas ganības, un Libnu un viņas ganības,',
        14: 'Un Jatiru un viņas ganības, un Estemou un viņas ganības,',
        15: 'Un Holonu un viņas ganības, un Debiru un viņas ganības,',
        16: 'Un Aīnu un viņas ganības, un Jūtu un viņas ganības, un BetŠemesu un viņas ganības, - deviņas pilsētas no šīm divām ciltīm.',
        17: 'Un no Benjamina cilts: Gibeonu un viņas ganības, Ģebu un viņas ganības,',
        18: 'Un Anatotu un viņas ganības, un Almonu un viņas ganības, - četras pilsētas.',
        19: 'Pavisam priestera Ārona dēliem bija trīspadsmit pilsētas ar savām ganībām.',
        20: 'Bet Kehāta bērnu radiem, tiem Levitiem, tiem citiem Kehāta bērniem krita caur mesliem tās pilsētas no Efraīma cilts.',
        21: 'Un tiem deva Šehemi, to glābšanās pilsētu priekš nokāvējiem, un viņas ganības Efraīma kalnos, un Ģezeru un viņas ganības,',
        22: 'Un Ķibcaīm un viņas ganības, un Bet-Oronu un viņas ganības, četras pilsētas.',
        23: 'Un no Dana cilts: Elteku un viņas ganības, un Ģibetonu un viņas ganības,',
        24: 'Un Ajaloni un viņas ganības, Gat-Rimonu un viņas ganības, - četras pilsētas.',
        25: 'Un no Manasus puscilts: Taēnaku un viņas ganības, un Gat-Rimonu un viņas ganības, divas pilsētas:',
        26: 'Pavisam kopā priekš tiem citiem Kehāta bērnu radiem desmit pilsētas ar savām ganībām.',
        27: 'Un Geršona bērniem no Levitu radiem (krita) no Manasus puscilts tā glābšanās pilsēta priekš nokāvējiem, Golana Basanā un viņas ganības un Beēstra un viņas ganības, - divas pilsētas.',
        28: 'Un no Īsašara cilts Ķisjone un viņas ganības, un Dobrate un viņas ganības,',
        29: 'Jarmute un viņas ganības, Enganim un viņas ganības, - četras pilsētas,',
        30: 'Un no Ašera cilts Mizeale un viņas ganības, Abdone un viņas ganības.',
        31: 'Elkata un viņas ganības, un Reoba un viņas ganības, - četras pilsētas.',
        32: 'Un no Naftalus cilts tā glābšanās pilsēta priekš nokāvējiem Ķedesā Galilejā un viņas ganības, Amot-Dore un viņas ganības, un Kartane un viņas ganības, - trīs pilsētas.',
        33: 'Pavisam Geršona bērniem pēc viņu radiem ir trīspadsmit pilsētas ar savām ganībām.',
        34: 'Un Merarus bērnu radiem, tiem citiem Levitiem, (krita) no Zebulona cilts Jokneane un viņas ganības, un Karta un viņas ganības,',
        35: 'Dimna un viņas ganības, Naālale un viņas ganības, - četras pilsētas.',
        36: 'Un no Rūbena cilts Becere un viņas ganības, Jāca un viņas ganības.',
        37: 'Ķedemota un viņas ganības, un Mepaāta un viņas ganības, - četras pilsētas.',
        38: 'Un no Gada cilts krita tā glābšanās pilsēta priekš nokāvējiem, Rāmote Gileādā un viņas ganības,',
        39: 'Un Mahānaīm un viņas ganības, Hešbona un viņas ganības, Jaēzere un viņas ganības, pavisam četras pilsētas.',
        40: 'Visas šīs pilsētas piederēja Merarus bērniem pēc viņu radiem, kas arī vēl bija no Levitu radiem, un caur mesliem tiem krita divpadsmit pilsētas.',
        41: 'Pavisam Levitu pilsētu Israēla bērnu zemē bija četrdesmit un astoņas ar savām ganībām.',
        42: 'Visas šīs pilsētas bija savrup ar savām apkārtējām ganībām; tā bija ar visām šīm pilsētām.',
        43: 'Tā Tas Kungs Israēlim deva visu to zemi, ko Viņš bija zvērējis dot viņu tēviem, un tie to uzņēma un tur dzīvoja.',
        44: 'Un Tas Kungs tiem deva mieru visapkārt, tā kā Tas Kungs viņu tēviem bija zvērējis, un no visiem viņu ienaidniekiem neviens nepastāvēja viņu priekšā, visus viņu ienaidniekus Tas Kungs deva viņu rokā.',
        45: 'Un neviena vārda netrūka no visiem tiem labiem vārdiem, ko Tas Kungs uz Israēla namu bija runājis, - viss tas notika.',
    },
    22: {
        1: 'Tad Jozuas aicināja Rūbeniešus un Gadiešus un Manasus puscilti,',
        2: 'Un uz tiem sacīja: jūs visu esat turējuši, ko jums Mozus, Tā Kunga kalps, pavēlējis, un esat klausījuši manai balsij visās lietās, ko es jums esmu pavēlējis.',
        3: 'Jūs savus brāļus neesat atstājuši tādu ilgu laiku līdz šai dienai, bet esat turējuši, kas bija jātur, Tā Kunga, sava Dieva pavēli.',
        4: 'Un nu Tas Kungs, jūsu Dievs, mieru ir devis jūsu brāļiem, tā kā Viņš tiem bija runājis. Tad nu griežaties atpakaļ un ejat uz saviem dzīvokļiem, uz savu īpašu zemi, ko jums Tā Kunga kalps Mozus devis viņpus Jardānes.',
        5: 'Bet no Dieva puses dariet to likumu un to bauslību, ko jums Mozus, Tā Kunga kalps, ir pavēlējis, ka jūs mīļojat To Kungu, savu Dievu, un staigājat visos Viņa ceļos un turat Viņa baušļus un Viņam pieķeraties un Viņam kalpojat no visas savas sirds un no visas savas dvēseles.',
        6: 'Tā Jozuas tos svētīja un atlaida, un tie aizgāja uz saviem dzīvokļiem.',
        7: 'Jo vienai Manasus cilts pusei Mozus to (daļu) bija devis Basanā, bet viņas otrai pusei Jozuas to daļu deva pie viņu brāļiem šaipus Jardānes pret vakariem.',
        8: 'Kad Jozuas tos atlaida uz viņu dzīvokļiem, tad viņš tos svētīja un uz tiem runāja sacīdams: ar lielu bagātību jūs griežaties atpakaļ uz saviem dzīvokļiem, ar varen daudz lopiem, ar sudrabu un zeltu un ar varu un ar dzelzi un ar ļoti daudz drēbēm. Daliet savu ienaidnieku laupījumu ar saviem brāļiem.',
        9: 'Tā Rūbena bērni un Gada bērni un Manasus puscilts griezās atpakaļ un aizgāja no Israēla bērniem no Šīlo Kanaāna zemē, un gāja uz Gileādas zemi, uz savu īpašu zemi, kur tie par mantiniekiem bija iecelti pēc Tā Kunga pavēles caur Mozu.',
        10: 'Kad tie nu nāca uz Jardānes apgabalu, kas Kanaāna zemē, tad Rūbena bērni un Gada bērni un Manasus puscilts tur uzcēla altāri pie Jardānes, lielu altāri, kur bija ko redzēt.',
        11: 'Un Israēla bērni dzirdēja sakām: Redzi, Rūbena bērni un Gada bērni un Manasus puscilts ir uzcēluši altāri Kanaāna zemei pretī, Jardānes apgabalā, Israēla bērniem pretim.',
        12: 'Kad Israēla bērni to dzirdēja, tad visa Israēla bērnu draudze sapulcējās Šīlo, ka tie pret viņiem celtos ar karaspēku.',
        13: 'Un Israēla bērni sūtīja pie Rūbena bērniem un pie Gada bērniem un pie Manasus puscilts uz Gileādas zemi Pinehasu, Eleazara, tā priestera, dēlu,',
        14: 'Un desmit virsniekus līdz ar viņu, no ikviena tēva nama vienu virsnieku no visām Israēla ciltīm, un ikviens no tiem bija tā galva savu tēvu namā pār Israēla tūkstošiem.',
        15: 'Un tie nāca pie Rūbena bērniem un pie Gada bērniem un pie Manasus puscilts Gileādas zemē, un runāja ar tiem un sacīja:',
        16: 'Tā saka visa Tā Kunga draudze: kas tas par noziegumu, ko jūs pret Israēla Dievu esat noziegušies, nogriezdamies šodien no Tā Kunga, ka jūs sev esat uztaisījuši altāri, Tam Kungam šodien pretī turēdamies?',
        17: 'Vai tas Peora noziegums mums vēl ir mazs, no kā mēs (vēl) neesam šķīstījušies līdz šai dienai, jebšu mocība Tā Kunga draudzē ir bijusi?',
        18: 'Un jūs šodien nogriežaties no Tā Kunga; bet notiks, kad jūs Tam Kungam šodien turēsities pretī, tad Viņš rīt dusmosies par visu Israēla draudzi.',
        19: 'Bet ja jums šķiet, savu iemantoto zemi nešķīstu esam, tad nāciet pāri uz Tā Kunga īpašu zemi, kur Tā Kunga dzīvoklis stāv, un ņemiet savu daļu mūsu vidū, bet neturaties pretī Tam Kungam, nedz turaties pretī mums, uzceldami sev altāri klāt pie Tā Kunga, mūsu Dieva, altāra.',
        20: 'Vai Akans, Zerus dēls, nebija ļoti noziedzies pie tā, kas bija izdeldējams? Un bardzība nāca pār visu Israēla draudzi, un tas vīrs nenomira viens vien sava nozieguma dēļ.',
        21: 'Tad Rūbena bērni un Gada bērni un Manasus puscilts atbildēja un runāja uz Israēla tūkstošu virsniekiem:',
        22: 'Tas stiprais Dievs, Dievs, Tas Kungs, tas stiprais Dievs, Dievs, Tas Kungs, tas zin, un arī Israēlim būs zināt, ja tas ir no pretestības vai caur noziegumu pret To Kungu, tad lai Viņš mums šodien nepalīdz.',
        23: 'Ja mēs tāpēc sev altāri esam uzcēluši, ka gribam nogriezties no Tā Kunga, vai uz tā upurēt dedzināmos upurus vai ēdamus upurus vai pateicības upurus, tad lai Tas Kungs to piemeklē;',
        24: 'Un ja mēs to neesam darījuši šo lietu bīdamies un sacīdami: rītu jūsu bērni uz mūsu bērniem runās un sacīs: kas jums par daļu ar To Kungu, Israēla Dievu?',
        25: 'Tas Kungs par robežu ir licis to Jardāni starp mums un jums, jūs Rūbena bērni un jūs Gada bērni, jums nav daļas pie Tā Kunga; tad jūsu bērni mūsu bērniem liktu atstāties no Tā Kunga bijāšanas.',
        26: 'Tāpēc mēs sacījām: taisīsim jel sev un uzcelsim altāri, ne dedzināmiem upuriem, nedz kaujamiem upuriem,',
        27: 'Bet ka tas būtu par liecinieku starp mums un jums, un starp mūsu radiem pēc mums, ka mēs Tam Kungam ar kalpošanu varam kalpot Viņa priekšā, ar saviem dedzināmiem upuriem un ar saviem kaujamiem upuriem un ar saviem pateicības upuriem, un lai jūsu bērni turpmāk uz mūsu bērniem nevar sacīt: jums nav daļas pie Tā Kunga.',
        28: 'Tāpēc mēs sacījām: kad notiek, ka tie uz mums vai uz mūsu pēcnākamiem turpmāk tā sacīs; tad mēs sacīsim: redziet Tā Kunga altāra taisījumu, ko mūsu tēvi ir taisījuši, ne dedzināmiem upuriem, nedz kaujamiem upuriem, bet par liecību starp jums un mums.',
        29: 'Lai tas ir tālu no mums, ka mēs būtu pretī turējušies Tam Kungam, vai šodien no Tā Kunga nogriezušies, uzceldami vēl vienu altāri dedzināmiem upuriem, ēdamiem upuriem un kaujamiem upuriem klāt pie Tā Kunga, mūsu Dieva, altāra, kas ir Viņa dzīvokļa priekšā.',
        30: 'Kad priesteris Pinehas un tie draudzes virsnieki un tās galvas pār Israēla tūkstošiem, kas pie tā bija, dzirdēja tos vārdus, ko Rūbena bērni un Gada bērni un Manasus bērni runāja, tad tas viņiem patika.',
        31: 'Un Pinehas, priestera Eleazara dēls, sacīja uz Rūbena bērniem un uz Gada bērniem un uz Manasus bērniem: šodien mēs atzīstam, ka Tas Kungs ir mūsu vidū, ka jūs ar šo noziegumu neesat noziegušies pret To Kungu; nu jūs Israēla bērnus esat izglābuši no Tā Kunga rokas.',
        32: 'Tad Pinehas, priestera Eleazara dēls, un tie virsnieki griezās atpakaļ no Rūbena bērniem un no Gada bērniem no Gileāda zemes uz Kanaāna zemi pie Israēla bērniem un viņiem atsacīja šo vārdu.',
        33: 'Un tas vārds patika Israēla bērniem, un Israēla bērni teica Dievu un vairs nedomāja pret viņiem celties ar karaspēku nedz to zemi postīt, kur Rūbena bērni un Gada bērni dzīvoja.',
        34: 'Un Rūbena bērni un Gada bērni nosauca to altāri: lai tas ir par liecinieku starp mums, ka Tas Kungs ir Dievs.',
    },
    23: {
        1: 'Un pēc ilga laika, kad Tas Kungs Israēlim mieru bija devis no visiem viņu ienaidniekiem visapkārt, un kad Jozuas bija vecs palicis un stipri gados,',
        2: 'Tad Jozuas sasauca visus Israēla vecajus un viņu virsniekus un viņu soģus un viņu priekšniekus un uz tiem sacīja: es esmu vecs palicis un stipri gados, -',
        3: 'Un jūs visu esat redzējuši, ko Tas Kungs, jūsu Dievs, darījis visām šīm tautām jūsu priekšā, jo Tas Kungs, jūsu Dievs, tas priekš jums ir karojis.',
        4: 'Redziet, šās atlikušās tautas es caur mesliem jums esmu devis par daļu jūsu ciltīm, no Jardānes (sākot), un visas tautas, ko es esmu izdeldējis, un līdz tai lielai jūrai pret saules noiešanu.',
        5: 'Un Tas Kungs, jūsu Dievs, pats tos izdzīs jūsu priekšā un tos no jums aizdzīs, un jūs iemantosiet viņu zemi, tā kā Tas Kungs, jūsu Dievs, uz jums runājis.',
        6: 'Tad nu esat ļoti stipri, turēt un darīt visu, kas rakstīts Mozus bauslības grāmatā, ka jūs no tās neatkāpjaties ne uz labo, ne uz kreiso pusi.',
        7: 'Ka jūs nenoejat pie šīm tautām, kas pie jums atlikušas, un nepieminiet viņu dievu vārdu, un nezvērējiet pie viņiem un nekalpojiet viņiem un nemetaties zemē priekš viņiem,',
        8: 'Bet pieķeraties Tam Kungam, savam Dievam, kā jūs esat darījuši līdz šai dienai.',
        9: 'Tā Tas Kungs jūsu priekšā ir izdzinis lielas un varenas tautas, un neviens priekš jums nav pastāvējis līdz šai dienai.',
        10: 'Viens vīrs no jums dzen tūkstošus, jo Tas Kungs, jūsu Dievs, Tas priekš jums karo, tā kā Viņš jums runājis.',
        11: 'Tāpēc sargājat savas dvēseles ļoti, ka jūs mīļojat To Kungu, savu Dievu.',
        12: 'Jo kad jūs nogriezīsities un pieķersities šīm tautām, kas pie jums atlikušas un apsvainosities(saradosities) ar viņām un iesiet pie viņām un tās pie jums,',
        13: 'Tad ziniet tiešām, ka Tas Kungs, jūsu Dievs, joprojām visas šās tautas jūsu priekšā neizdzīs, bet tās jums tiks par slazda valgu un par tīklu un par pātagu jūsu sānos un par ērkšķiem jūsu acīs, tiekams jūs iesiet bojā no šīs labās zemes, ko Tas Kungs, jūsu Dievs, jums devis.',
        14: 'Un redzi, es aizeju šodien visas pasaules ceļu; tad nu atzīstat no visas sirds un no visas dvēseles, ka neviena vārda netrūkst no visiem labiem vārdiem, ko Tas Kungs, jūsu Dievs, uz jums runājis; visi jums ir nākuši, no tiem netrūkst neviena vārda.',
        15: 'Un kā viss tas labums pār jums nācis, ko Tas Kungs, jūsu Dievs, uz jums runājis: tā Tas Kungs, jūsu Dievs, uz jums liks nākt visam tam ļaunumam, ko Viņš runājis, tiekams Viņš jūs būs izdeldējis no šīs labās zemes virsas, ko Tas Kungs, jūsu Dievs, jums devis,',
        16: 'Kad jūs Tā Kunga, sava Dieva, derību pārkāpjat, ko Viņš jums ir devis, un ejat un kalpojat citiem dieviem un metaties zemē priekš viņiem, tad Tā Kunga bardzība pret jums iedegsies un jūs piepeši izdeldēs no tās labās zemes virsas, ko Viņš jums devis.',
    },
    24: {
        1: 'Un Jozuas sapulcināja visas Israēla ciltis Šehemē un sasauca Israēla vecajus un viņu virsniekus un viņu soģus un viņu priekšniekus, un tie atnāca Dieva priekšā.',
        2: 'Tad Jozuas sacīja uz visiem tiem ļaudīm: tā saka Tas Kungs, Israēla Dievs: viņpus upes jūsu tēvi vecos laikos ir dzīvojuši, Tārus, Ābrahāma un Nahora tēvs, un ir kalpojuši citiem dieviem.',
        3: 'Tad Es ņēmu jūsu tēvu Ābrahāmu no viņas upes puses un tam liku staigāt caur visu Kanaāna zemi, un Es vairoju arī viņa dzimumu un devu viņam Īzaku.',
        4: 'Un Īzakam Es devu Jēkabu un Ēsavu, un Ēsavam Es devu Seīra kalnus par daļu, bet Jēkabs un viņa bērni nogāja uz Ēģiptes zemi.',
        5: 'Tad Es sūtīju Mozu un Āronu, un mocīju Ēģiptes zemi, tā kā Es viņas vidū esmu darījis, un pēc tam Es jūs izvedu.',
        6: 'Kad Es jūsu tēvus no Ēģiptes zemes biju izvedis, tad jūs nācāt pie jūras, un ēģiptieši jūsu tēviem dzinās pakaļ ar ratiem un ar jātniekiem līdz niedru jūrai.',
        7: 'Tad tie brēca uz To Kungu, un Viņš lika tumsību starp jums un ēģiptiešiem, un Viņš lika jūrai pār tiem nākt un tos apklāja, un jūsu acis redzējušas, ko Es Ēģiptes zemē esmu darījis. Pēc tam jūs ilgu laiku esat dzīvojuši tuksnesī.',
        8: 'Un Es jūs vedu Amoriešu zemē, kas viņpus Jardānes dzīvoja: tie pret jums karoja, bet Es tos nodevu jūsu rokā, un jūs iemantojāt viņu zemi, un Es tos izdeldēju jūsu priekšā.',
        9: 'Tad Balaks, Cipora dēls, Moabiešu ķēniņš, cēlās un karoja pret Israēli; un viņš nosūtīja un lika aicināt Bileāmu, Beora dēlu, jūs nolādēt.',
        10: 'Bet Es Bileāmu negribēju klausīt, un viņš svētīdams jūs svētīja, un Es jūs izglābu no viņa rokas.',
        11: 'Un jūs cēlāties pār Jardāni un nācāt uz Jēriku; tad Jērikus iedzīvotāji pret jums karoja, Amorieši, Ferezieši un Kanaānieši un Hetieši un Ģirgozieši un Hivieši un Jebusieši, bet Es tos nodevu jūsu rokās.',
        12: 'Un Es sūtīju jūsu priekšā dundurus, tie tos priekš jums izdzina, kā arī tos divus Amoriešu ķēniņus, ne caur tavu zobenu, ne caur tavu stopu.',
        13: 'Un Es jums devu zemi, ko tu neesi apkopis, un pilsētas, ko jūs neesat uzcēluši, ka tur dzīvojat, vīna dārzus un eļļas kokus, ko jūs neesat dēstījuši, ka no tiem ēdat.',
        14: 'Un nu bīstaties To Kungu un kalpojiet Viņam skaidri un taisni, un atmetiet tos dievus, kam jūsu tēvi viņpus upes un Ēģiptes zemē ir kalpojuši, un kalpojiet Tam Kungam.',
        15: 'Bet ja tas jums nepatiks, Tam Kungam kalpot, tad izvēlaties sev šodien, kam jūs gribat kalpot, vai tiem dieviem, kam jūsu tēvi kalpojuši viņpus upes, vai tiem Amoriešu dieviem, kuru zemē jūs dzīvojat. Bet es un mans nams, mēs kalposim Tam Kungam.',
        16: 'Tad tie ļaudis atbildēja un sacīja: lai tas ir tālu no mums, To Kungu atstāt un kalpot citiem dieviem.',
        17: 'Jo Tas Kungs ir mūsu Dievs; Tas mūs un mūsu tēvus izvedis no Ēģiptes zemes, no tā vergu nama, Tas priekš mums šās lielās zīmes darījis un mūs pasargājis uz visiem ceļiem, kur esam gājuši, un starp visiem ļaudīm, caur kuru vidu esam staigājuši.',
        18: 'Un Tas Kungs mūsu priekšā izdzinis visus tos ļaudis un tos Amoriešus, šās zemes iedzīvotājus, tāpēc mēs kalposim Tam Kungam, jo Tas ir mūsu Dievs.',
        19: 'Tad Jozuas sacīja uz tiem ļaudīm: jūs nevarēsiet Tam Kungam kalpot, jo Tas Kungs ir svēts Dievs, Viņš ir stiprs Dievs, dusmotājs, Viņš nepiedos jūsu pārkāpumus, nedz jūsu grēkus.',
        20: 'Kad jūs no Tā Kunga atstāsities un kalposiet svešiem dieviem, tad Viņš atstāsies un jums darīs ļaunu, un jums liks bojā iet, pēc tam, kad Viņš jums labu darījis.',
        21: 'Tad tie ļaudis sacīja uz Jozua: nē, bet mēs kalposim Tam Kungam.',
        22: 'Tad Jozuas sacīja uz tiem ļaudīm: jūs esat liecinieki sev pašiem, ka jūs To Kungu esat izvēlējušies, Viņam kalpot. Un tie sacīja: mēs esam liecinieki.',
        23: 'Un nu atmetiet tos svešos dievus, kas jūsu starpā, un griežat savas sirdis uz To Kungu, Israēla Dievu.',
        24: 'Un tie ļaudis sacīja uz Jozua: mēs kalposim Tam Kungam, mūsu Dievam, un klausīsim Viņa balsi.',
        25: 'Tā Jozuas tai dienā darīja derību ar tiem ļaudīm, un tiem iecēla likumus un tiesas Šehemē.',
        26: 'Un Jozuas rakstīja šos vārdus Dieva bauslības grāmatā un ņēma lielu akmeni un to tur uzcēla apakš ozola pie Tā Kunga svētās vietas.',
        27: 'Un Jozuas sacīja uz visiem ļaudīm: redzi, šis akmens mums būs par liecību; jo tas ir dzirdējis visus Tā Kunga vārdus, ko Viņš ar mums runājis, - tas būs jums par liecību, ka jūs savam Dievam nemelojat.',
        28: 'Tā Jozuas tos ļaudis atlaida, ikvienu savā īpašumā.',
        29: 'Un notikās pēc šīm lietām, tad Jozuas, Nuna dēls, Tā Kunga kalps, nomira, simts un desmit gadus vecs būdams.',
        30: 'Un tie viņu apraka viņa īpašuma robežās, Timnat-Zerā, kas ir Efraīma kalnos, no Gaāša kalna pret ziemeļiem.',
        31: 'Un Israēls kalpoja Tam Kungam, kamēr Jozuas dzīvoja un kamēr tie vecaji dzīvoja, kas ilgi pēc Jozuas dzīvoja un kas visus Tā Kunga darbus zināja, ko Viņš Israēlim bija darījis.',
        32: 'Un tie apraka arīdzan Jāzepa kaulus, ko Israēla bērni no Ēģiptes zemes bija izveduši, Šehemē, tai tīruma gabalā, ko Jēkabs no Hamora, Šehema tēva, bērniem bija pircis par simts sudraba gabaliem; jo tas Jāzepa bērniem bija ticis par daļu.',
        33: 'Un Eleazars, Ārona dēls, nomira, un viņu apraka Ģibejā, viņa dēla Pinehasa pilsētā, kas viņam bija dota Efraīma kalnos.',
    },
}
